window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[152]={"id":"152","numero":152,"titre":"Endocardite infectieuse","objectifs":[{"id":"152-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d'une endocardite infectieuse (EI)","contenu":"<div class=\"notion-course\"><p>L'<strong><span>endocardite infectieuse</span></strong> (EI) est une <span>infection de l'endocarde</span>, touchant le plus souvent une ou plusieurs <strong>valves cardiaques natives</strong>, mais pouvant aussi intéresser l'<span>endocarde pariétal</span> ou tout <strong><span class=\"nc-red nc-bold\">matériel intracardiaque</span> implanté</strong> :</p>\n      <ul>\n        <li><span><span class=\"nc-red_bg\">Prothèses valvulaires</span></span> ;</li>\n        <li><span>Sondes de stimulateur</span> ou de <span>défibrillateur</span> ;</li>\n        <li><span>Assistances ventriculaires</span> ;</li>\n        <li><span>Cathéter veineux central</span>.</li>\n      </ul>\n      <p><span>Les</span> valves du <strong>cœur gauche</strong> (<span>mitrale</span>, <span>aortique</span>) sont <span>plus souvent touchées</span> que celles du cœur droit.</p>\n      <div class=\"callout callout-info\"><strong>À distinguer.</strong> <span>Les</span> <span>endocardites non infectieuses</span>, beaucoup plus rares, peuvent compliquer un <span>cancer</span> (<span class=\"nc-orange_bg\">endocardites </span><span><span class=\"nc-orange_bg\">marastiques</span></span>) ou une <span>maladie auto-immune</span> — <span><span class=\"nc-orange_bg\">lupus</span></span> (lésions de <span>Libman-Sacks</span>), <span><span class=\"nc-orange_bg\">SAPL</span></span>.</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-152.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 152</a></li><li><a href=\"https://www.infectiologie.com/fr/actualites/endocardite-antibiotherapie-position-spilf-aepei-diaporama-du-groupe-reco_-n.html\" target=\"_blank\" rel=\"noopener noreferrer\">SPILF–AEPEI · antibiothérapie et prophylaxie de l’endocardite, 2025</a></li></ul></details>","frequence":0},{"id":"152-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l'épidémiologie de l'EI","contenu":"<div class=\"notion-course\"><p>L'<span><span class=\"nc-red nc-bold\">incidence</span></span><span class=\"nc-red nc-bold\"> de l'EI </span><span><span class=\"nc-red nc-bold\">n'a pas diminué</span></span> ces dernières décennies, mais le <strong>profil des patients</strong> et la répartition des micro-organismes se sont modifiés : <span>vieillissement de la population</span>, progrès médicaux, <span>régression des valvulopathies post-rhumatismales</span>.</p>\n      <p><span>Les</span> patients atteints sont désormais plus âgés et/ou exposés par d'autres situations :</p>\n      <ul>\n        <li><span><span class=\"nc-brown_bg\">Valvulopathies dégénératives</span></span> — fibrose, prolapsus mitral ;</li>\n        <li><span><span class=\"nc-brown_bg\">Toxicomanie intraveineuse</span></span> ;</li>\n        <li><span>Procédures de soins à risque</span> — circulation extracorporelle, cathéters veineux, hémodialyse, stimulateur/<span>défibrillateur</span>, chambre implantable.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Bascule microbiologique.</strong> Autrefois <span>les</span> <span><span class=\"nc-purple nc-bold\">streptocoques oraux</span></span> étaient majoritaires ; aujourd'hui le premier germe est le <span>staphylocoque</span>.</div>\n      <table>\n        <thead><tr><th>Donnée</th><th>Repère EDN</th></tr></thead>\n        <tbody>\n          <tr><td>Sex-ratio</td><td>Prédominance <strong>masculine</strong></td></tr>\n          <tr><td>Âge</td><td>Âge moyen <span>62 ans</span> ; plus fréquente <span class=\"nc-pink nc-bold\">après </span><span><span class=\"nc-pink nc-bold\">70 ans</span></span></td></tr>\n          <tr><td><span>Mortalité</span> hospitalière</td><td><span>15-30 %</span><br>1ʳᵉ cause de décès : <span>insuffisance cardiaque</span><br>2ᵉ cause : <span><span class=\"nc-red nc-bold\">emboles cérébraux</span></span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Facteurs de mauvais <span>pronostic</span></strong> :</p>\n      <ul>\n        <li><span><span class=\"nc-red nc-bold\">Insuffisance cardiaque aiguë</span></span>, <span><span class=\"nc-red nc-bold\">complications neurologiques</span></span>, <span><span class=\"nc-red nc-bold\">syndrome infectieux mal maîtrisé</span></span>, <span><span class=\"nc-red nc-bold\">abcès intracardiaques</span></span>, <span><span class=\"nc-red nc-bold\">végétations volumineuses</span></span> ;</li>\n        <li>EI sur <strong>prothèse</strong> ;</li>\n        <li>Micro-organismes très virulents — <span><span class=\"nc-red nc-bold\">Staphylococcus aureus</span></span> et <span><span class=\"nc-red nc-bold\">champignons</span></span> ;</li>\n        <li><span>Terrain</span> fragile — <span><span class=\"nc-red nc-bold\">âge avancé</span></span>, <span><span class=\"nc-red nc-bold\">diabète</span></span>, <span><span class=\"nc-red nc-bold\">immunodépression</span></span>, insuffisances cardiaque / rénale / respiratoire.</li>\n      </ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-152.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 152</a></li><li><a href=\"https://www.infectiologie.com/fr/actualites/endocardite-antibiotherapie-position-spilf-aepei-diaporama-du-groupe-reco_-n.html\" target=\"_blank\" rel=\"noopener noreferrer\">SPILF–AEPEI · antibiothérapie et prophylaxie de l’endocardite, 2025</a></li></ul></details>","frequence":2},{"id":"152-3","rang":"A","rubrique":"Epidémiologie","titre":"Connaître les situations à risque d'EI (cardiopathie du groupe A, présence de matériel intra-cardiaque, bactériémie à cocci Gram positif)","contenu":"<div class=\"notion-course\"><ul><li>Haut risque : antécédent d’endocardite, prothèse valvulaire (TAVI compris), matériel de réparation valvulaire, certaines cardiopathies congénitales cyanogènes ou réparées avec matériel, selon délai et lésion résiduelle. Les assistances ventriculaires relèvent d’un cadre spécialisé.</li><li>Ne pas classer automatiquement un filtre cave, un stent ou toute prothèse vasculaire dans le groupe ouvrant droit à prophylaxie dentaire. Un stimulateur/défibrillateur expose à l’infection de matériel mais n’équivaut pas à une prothèse valvulaire.</li><li>Une bactériémie à S. aureus, <span class=\"nc-green_bg\">entérocoque</span> ou certains <span class=\"nc-purple_bg nc-bold\">streptocoques</span> fait rechercher une endocardite selon contexte. L’absence de cardiopathie connue ne l’exclut pas.</li></ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-152.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 152</a></li><li><a href=\"https://www.infectiologie.com/fr/actualites/endocardite-antibiotherapie-position-spilf-aepei-diaporama-du-groupe-reco_-n.html\" target=\"_blank\" rel=\"noopener noreferrer\">SPILF–AEPEI · antibiothérapie et prophylaxie de l’endocardite, 2025</a></li></ul></details>","frequence":0},{"id":"152-4","rang":"A","rubrique":"Étiologies","titre":"Connaître les principaux agents infectieux à l'origine d'EI (bactéries, levures)","contenu":"<div class=\"notion-course\"><p>Le micro-organisme en cause est une <span>bactérie</span> ou, plus rarement, un <span>champignon</span> (levure). <strong><span>Staphylocoques</span>, <span class=\"nc-purple_bg nc-bold\">streptocoques</span> et <span>entérocoques</span></strong> représentent à eux seuls <span>~80 %</span> des EI.</p>\n      <table>\n        <thead><tr><th>Agent <span>infectieux</span></th><th>Fréquence</th><th>Particularité EDN</th></tr></thead>\n        <tbody>\n          <tr><td><span>Staphylococcus aureus</span><br>CG+ en amas</td><td><span>30 %</span></td><td><span>1ᵉʳ germe</span> ; EI <span>les</span> plus graves</td></tr>\n          <tr><td><span>Streptocoques oraux</span><br>CG+ en <span class=\"nc-blue\">chaînette</span> (S. sanguis, mitis, salivarius, mutans)</td><td><span>20 %</span></td><td><span><span class=\"nc-orange_bg\">Porte d'entrée</span></span> <span><span class=\"nc-blue_bg\">bucco-dentaire</span></span></td></tr>\n          <tr><td><span>Streptocoques du groupe D</span><br>S. gallolyticus (bovis)</td><td><span>13 %</span></td><td>Imposent la recherche d'un <span>cancer colique</span></td></tr>\n          <tr><td><span>Staphylocoques à coagulase négative</span><br>S. epidermidis, S. lugdunensis</td><td><span>10 %</span></td><td>Fréquence <span>en augmentation</span>, surtout EI sur prothèse</td></tr>\n          <tr><td><span>Entérocoques</span><br>E. faecalis, E. faecium</td><td><span>10 %</span></td><td><span><span class=\"nc-orange_bg\">Porte d'entrée</span></span> <span><span class=\"nc-red_bg\">digestive</span></span> et <span><span class=\"nc-purple_bg\">urinaire</span></span></td></tr>\n          <tr><td>Groupe <span>HACEK</span><br><em><span>Haemophilus</span>, Aggregatibacter, Cardiobacterium, Eikenella, Kingella</em></td><td><span>5 %</span></td><td>Croissance lente — <span>hémocultures</span> parfois négatives</td></tr>\n          <tr><td><span><span class=\"nc-purple nc-bold\">Candida</span></span> et autres champignons (levures)</td><td><span>&lt; 5 %</span></td><td>EI fongiques — <span>pronostic sévère</span></td></tr>\n          <tr><td>Autres — <span><span class=\"nc-purple nc-bold\">Coxiella burnetii</span></span>, <span class=\"nc-purple nc-bold\">Bartonella</span>, <span class=\"nc-purple nc-bold\">Brucella</span>, <span><span class=\"nc-purple nc-bold\">Chlamydia</span></span>, <span class=\"nc-purple nc-bold\">Tropheryma whipplei</span></td><td><span>&lt; 5 %</span></td><td>EI à <span>hémocultures négatives</span></td></tr>\n          <tr><td>Aucun germe retrouvé malgré le bilan</td><td><span>5-10 %</span></td><td>EI à <span>hémocultures négatives</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 301 — Tumeur colon - rectum</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-152.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 152</a></li><li><a href=\"https://www.infectiologie.com/fr/actualites/endocardite-antibiotherapie-position-spilf-aepei-diaporama-du-groupe-reco_-n.html\" target=\"_blank\" rel=\"noopener noreferrer\">SPILF–AEPEI · antibiothérapie et prophylaxie de l’endocardite, 2025</a></li></ul></details>","frequence":1},{"id":"152-5","rang":"A","rubrique":"Physiopathologie","titre":"Connaître les portes d'entrée en fonction de l'agent infectieux","contenu":"<div class=\"notion-course\"><p>La <span><span class=\"nc-orange_bg\">porte d'entrée</span></span> est le site <span>infectieux</span> d'où part la <span>bactériémie</span>. Elle <strong>dépend du micro-organisme</strong>, oriente le bilan, mais n'est identifiée que dans <span>~50 %</span> des cas.</p>\n      <table>\n        <thead><tr><th>Agent</th><th><span><span class=\"nc-orange_bg\">Porte d'entrée</span></span></th><th>Bilan orienté</th></tr></thead>\n        <tbody>\n          <tr><td><span><span class=\"nc-purple nc-bold\">S. aureus</span></span>, staph. à coagulase négative, <span>Candida</span></td><td><strong><span class=\"nc-yellow_bg\">Cutanée</span></strong> — plaies, cathéters veineux ou de dialyse, toxicomanie IV, geste peropératoire, stimulateur/<span>défibrillateur</span></td><td><span>Culture du cathéter</span> ; <span>hémocultures</span></td></tr>\n          <tr><td><span><span class=\"nc-purple_bg\">Streptocoques oraux</span></span>, <span class=\"nc-orange_bg\">groupe </span><span><span class=\"nc-orange_bg\">HACEK</span></span></td><td><strong><span class=\"nc-blue_bg\">Bucco-dentaire</span></strong></td><td><span><span class=\"nc-blue_bg\">Panoramique dentaire</span></span> ; consultation stomatologique</td></tr>\n          <tr><td><span><span class=\"nc-purple nc-bold\">Streptocoques du groupe D</span></span> (<span class=\"nc-purple_bg\">S. gallolyticus</span>)</td><td><strong><span class=\"nc-red_bg\">Digestive</span></strong> — cancer, polypes, diverticules coliques</td><td><span><span class=\"nc-blue nc-bold\">Coloscopie</span> systématique</span></td></tr>\n          <tr><td><span><span class=\"nc-purple_bg\">Entérocoques</span></span></td><td><strong>Digestive</strong> et <strong>urinaire</strong></td><td><span><span class=\"nc-blue nc-bold\">ECBU</span></span> ; <span><span class=\"nc-blue nc-bold\">écho abdomino-pelvienne</span></span> ; ± <span><span class=\"nc-blue nc-bold\">coloscopie</span></span></td></tr>\n        </tbody>\n      </table></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-152.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 152</a></li><li><a href=\"https://www.infectiologie.com/fr/actualites/endocardite-antibiotherapie-position-spilf-aepei-diaporama-du-groupe-reco_-n.html\" target=\"_blank\" rel=\"noopener noreferrer\">SPILF–AEPEI · antibiothérapie et prophylaxie de l’endocardite, 2025</a></li></ul></details>","frequence":1},{"id":"152-6","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les cardiopathies à risque d'EI du groupe B","contenu":"<div class=\"notion-course\"><p>Le <span>groupe B</span> rassemble <span>les</span> cardiopathies à <strong>risque intermédiaire</strong> d'EI :</p>\n      <ul>\n        <li><span><span class=\"nc-brown_bg\">Valvulopathies dégénératives</span></span> ;</li>\n        <li><span class=\"nc-orange_bg\">Valvulopathies congénitales n'entrant pas dans le groupe A</span> — ex. <span>bicuspidie aortique</span> ;</li>\n        <li><span><span class=\"nc-orange_bg\">Cardiopathie post-rhumatismale</span></span> ;</li>\n        <li><span><span class=\"nc-orange_bg\">Cardiomyopathie hypertrophique</span></span> ;</li>\n        <li><span><span class=\"nc-pink_bg\">Stimulateur</span></span><span class=\"nc-pink_bg\"> et </span><span><span class=\"nc-pink_bg\">défibrillateur</span></span><span class=\"nc-pink_bg\"> cardiaque implantables</span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Discriminant.</strong> Le groupe B est à risque intermédiaire : il <span>ne relève pas de l'antibioprophylaxie</span>, réservée au seul <span>groupe A</span> (haut risque). Tous deux relèvent en revanche de l'<span>éducation à la santé</span>.</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-152.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 152</a></li><li><a href=\"https://www.infectiologie.com/fr/actualites/endocardite-antibiotherapie-position-spilf-aepei-diaporama-du-groupe-reco_-n.html\" target=\"_blank\" rel=\"noopener noreferrer\">SPILF–AEPEI · antibiothérapie et prophylaxie de l’endocardite, 2025</a></li></ul></details>","frequence":0},{"id":"152-7","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques évocateurs EI","contenu":"<div class=\"notion-course\"><p>Le tableau évocateur d'EI repose sur l'association d'une <span><span class=\"nc-yellow_bg\">fièvre</span></span> avec au moins l'un des éléments suivants : <strong>cardiopathie à risque</strong>, <strong><span class=\"nc-yellow_bg\">souffle cardiaque</span></strong>, <strong><span class=\"nc-yellow_bg\">accident </span><span><span class=\"nc-yellow_bg\">ischémique</span></span></strong>, <strong><span><span class=\"nc-yellow_bg\">purpura</span></span></strong> ou <strong><span class=\"nc-yellow_bg\">lombalgie</span></strong>.</p>\n      <table>\n        <thead><tr><th>Domaine</th><th>Signes</th></tr></thead>\n        <tbody>\n          <tr><td><span>Syndrome <span>infectieux</span></span></td><td><span>Fièvre</span> ; <span>AEG</span> ; <span>splénomégalie</span> (<span>20-30 %</span>)</td></tr>\n          <tr><td>Signes cardiaques</td><td><strong>Souffle :</strong> apparition ou modification d'un <span>souffle</span> — grande valeur diagnostique ; <span>son absence n'élimine pas le diagnostic</span><br><strong><span>Insuffisance cardiaque</span> :</strong> <span>fébrile</span>, surtout gauche<br><strong>Conduction :</strong> <span>syncope</span> ou <span>lipothymie</span> par <span><span class=\"nc-red nc-bold\">BAV</span></span> (<span><span class=\"nc-pink nc-bold\">abcès</span></span><span class=\"nc-pink nc-bold\"> septal</span>)<br><strong><span class=\"nc-orange_bg\">Péricardite</span> :</strong> plus rare</td></tr>\n          <tr><td>Phénomènes <strong>vasculaires</strong><br>(emboles septiques)</td><td><span>Lésions de Janeway</span> — <span>érythème</span> palmoplantaire indolore<br><span>Hémorragies sous-unguéales</span> « en flammèche »<br>Emboles artériels ; anévrismes mycotiques</td></tr>\n          <tr><td>Phénomènes <strong>immunologiques</strong><br>(complexes immuns)</td><td><span class=\"nc-blue_bg\">Faux </span><span><span class=\"nc-blue_bg\">panaris</span></span><span class=\"nc-blue_bg\"> d'</span><span><span class=\"nc-blue_bg\">Osler</span></span> — <span class=\"nc-blue nc-bold\">nodosités douloureuses</span>, fugaces, pulpe des doigts/orteils<br><span>Taches de Roth</span> — exsudats hémorragiques rétiniens (<span>fond d'œil</span>)<br><span>Glomérulonéphrite</span> ; <span>facteur rhumatoïde</span><br><span>Purpura vasculaire</span></td></tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/152/signes-peripheriques.jpg\" alt=\"Quatre signes périphériques de l&#x27;endocardite infectieuse : hémorragie sous-unguéale en flammèche, nodosité d&#x27;Osler à la pulpe des doigts, tache de Roth au fond d&#x27;œil, lésion de Janeway palmaire\" loading=\"lazy\">\n        <figcaption>Signes périphériques de l'<span>endocardite</span> infectieuse — hémorragie sous-unguéale « en flammèche », faux <span>panaris</span> d'Osler (nodosité douloureuse, pulpe des doigts), tache de Roth (exsudat <span>hémorragique</span> rétinien) et <span>lésion</span> de Janeway (érythème palmoplantaire indolore). Source : fiche source EDN item 152.</figcaption>\n      </figure>\n      <p>Cette planche illustre <span>les</span> quatre signes périphériques : l'<span>hémorragie sous-unguéale</span> et la <span>lésion de Janeway</span> sont des phénomènes <strong>vasculaires</strong> (emboles septiques) ; la <span>nodosité d'Osler</span> et la <span>tache de Roth</span> sont des phénomènes <strong>immunologiques</strong> (dépôts de complexes immuns).</p>\n      <div class=\"callout callout-warn\"><strong>Discriminant EDN — Osler <span>vs</span> Janeway.</strong> <span>Osler</span> = nodosité <span>douloureuse</span>, phénomène <strong>immunologique</strong>. <span>Janeway</span> = <span>macule</span> <span>indolore</span>, phénomène <strong>vasculaire</strong> (embole septique).</div>\n      <div class=\"callout callout-warn\"><strong>Tableaux trompeurs.</strong> <span><span class=\"nc-yellow_bg\">Fièvre</span></span> nue aiguë ou prolongée, <span>arthralgies</span> ou <span>lombalgies fébriles</span>, forme révélée par une complication inaugurale, ou alternance <span><span class=\"nc-yellow_bg\">fièvre</span></span> / apyrexie — la <span>récidive de la <span class=\"nc-yellow_bg\">fièvre</span> à l'arrêt d'une antibiothérapie</span> est très évocatrice.</div>\n      <p><strong>Forme aiguë <span>vs</span> subaiguë</strong> — la forme <span>aiguë</span> (<span>S. aureus</span>) associe <span>sepsis</span> au premier plan, <span>insuffisance cardiaque</span> et risque d'<span><span class=\"nc-red nc-bold\">AVC</span></span>. L'<span><span class=\"nc-green_bg\">endocardite</span></span><span class=\"nc-green_bg\"> </span><span><span class=\"nc-green_bg\">subaiguë d'Osler</span></span> (<span><span class=\"nc-green_bg\">streptocoque</span></span>, <span><span class=\"nc-green_bg\">entérocoque</span></span>) évolue sur plusieurs semaines : <span><span class=\"nc-yellow_bg\">fièvre</span> &gt; 8 jours</span>, <span>AEG</span>, phénomènes auto-immuns circulants.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 147 — <span>Fièvre</span> aiguë</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-152.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 152</a></li><li><a href=\"https://www.infectiologie.com/fr/actualites/endocardite-antibiotherapie-position-spilf-aepei-diaporama-du-groupe-reco_-n.html\" target=\"_blank\" rel=\"noopener noreferrer\">SPILF–AEPEI · antibiothérapie et prophylaxie de l’endocardite, 2025</a></li></ul></details>","frequence":2},{"id":"152-8","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la démarche initiale du diagnostic microbiologique","contenu":"<div class=\"notion-course\"><ul><li>Prélever plusieurs paires d’<span class=\"nc-yellow_bg nc-bold\">hémocultures</span> périphériques avant antibiotiques, sans attendre un pic fébrile. Le volume est déterminant : chez l’adulte, environ 10 mL/flacon, soit habituellement trois paires ; volumes pédiatriques adaptés.</li><li>En cas de <span class=\"nc-red nc-bold\">sepsis</span> ou indication urgente, regrouper les prélèvements rapidement et ne pas attendre 24 heures pour traiter. Chez le patient stable, respecter le protocole microbiologique d’endocardite.</li><li>Informer le laboratoire, préciser antibiotiques antérieurs et suspicion de germe difficile. Une incubation prolongée de 14 jours n’est pas obligatoire pour toutes les EI avec les systèmes actuels ; discuter les recherches spécifiques.</li></ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-152.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 152</a></li><li><a href=\"https://www.infectiologie.com/fr/actualites/endocardite-antibiotherapie-position-spilf-aepei-diaporama-du-groupe-reco_-n.html\" target=\"_blank\" rel=\"noopener noreferrer\">SPILF–AEPEI · antibiothérapie et prophylaxie de l’endocardite, 2025</a></li></ul></details>","frequence":0},{"id":"152-9","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître la démarche du diagnostic microbiologique quand les hémocultures initiales sont négatives","contenu":"<div class=\"notion-course\"><ul><li>Première cause d’hémocultures négatives : antibiotiques préalables. Vérifier volumes et modalités, contacter microbiologiste/infectiologue ; ne pas <span class=\"nc-pink nc-bold\">interrompre</span> automatiquement un traitement pour une fenêtre de 72 heures.</li><li>Selon expositions et contexte : sérologies Coxiella et <span class=\"nc-purple nc-bold\">Bartonella</span>, examens ciblés <span class=\"nc-purple nc-bold\">Brucella</span>, <span class=\"nc-blue_bg\">PCR</span> pour agents difficiles dont <span class=\"nc-purple nc-bold\">Tropheryma whipplei</span>, mycologie. Les techniques sont choisies avec le laboratoire.</li><li>Si chirurgie : analyse anatomopathologique, cultures et biologie moléculaire de la valve/matériel. En parallèle, considérer une endocardite non infectieuse.</li><li>Une bactérie rare ne doit pas être exclue par une affirmation absolue « ne donne jamais d’endocardite ». Rechercher surtout les causes probables et accessibles aux tests validés.</li></ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-152.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 152</a></li><li><a href=\"https://www.infectiologie.com/fr/actualites/endocardite-antibiotherapie-position-spilf-aepei-diaporama-du-groupe-reco_-n.html\" target=\"_blank\" rel=\"noopener noreferrer\">SPILF–AEPEI · antibiothérapie et prophylaxie de l’endocardite, 2025</a></li></ul></details>","frequence":0},{"id":"152-10","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la démarche initiale du diagnostic échocardiographie en cas de suspicion d'EI","contenu":"<div class=\"notion-course\"><p>L'<span><span class=\"nc-blue nc-bold\">échographie cardiaque</span></span> est, avec <span>les</span> <span>hémocultures</span>, l'un des deux <strong>piliers diagnostiques</strong> de l'EI.</p>\n      <table>\n        <thead><tr><th>Examen</th><th>Indication</th><th>Sensibilité</th></tr></thead>\n        <tbody>\n          <tr><td><span><span class=\"nc-blue_bg\">ETT</span></span> — transthoracique</td><td><strong>1ʳᵉ intention, systématique</strong> dans tous <span>les</span> cas</td><td><span>~70 %</span></td></tr>\n          <tr><td><span><span class=\"nc-blue_bg\">ETO</span></span> — transœsophagienne</td><td>Si <span><span class=\"nc-red nc-bold\">ETT</span></span><span class=\"nc-red nc-bold\"> positive</span> ; ou <span><span class=\"nc-red nc-bold\">ETT</span></span><span class=\"nc-red nc-bold\"> négative avec </span><span><span class=\"nc-red nc-bold\">forte suspicion</span></span> ; ou présence de <strong><span class=\"nc-red nc-bold\">matériel intracardiaque</span></strong></td><td><span>≥ 90 %</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> Une <span><span class=\"nc-green_bg\">échographie normale n'élimine pas</span></span><span class=\"nc-green_bg\"> le diagnostic</span>. En cas de <span class=\"nc-red nc-bold\">forte suspicion</span> clinique, elle doit être <strong>répétée à <span><span class=\"nc-pink nc-bold\">J7-J10</span></span></strong> (<span><span class=\"nc-blue_bg\">ETT</span></span> + <span><span class=\"nc-blue_bg\">ETO</span></span>).</div>\n      <p>Le <span>diagnostic positif</span> s'appuie sur <span>les</span> <strong><span>critères diagnostiques</span> de Duke modifiés (<span>2023</span>)</strong>, qui combinent critères <span>majeurs</span> et <span>mineurs</span> :</p>\n      <table>\n        <thead><tr><th><span>Critères majeurs</span> (2)</th><th><span>Critères mineurs</span> (5)</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>\n              <strong><span>Hémocultures</span> positives pour l'EI :</strong>\n              <ul>\n                <li><span>≥ 2 hémocultures</span> à micro-organisme <strong>typique d'EI</strong> (<span><span class=\"nc-purple nc-bold\">S. aureus</span></span>, <span><span class=\"nc-purple nc-bold\">streptocoques oraux</span></span>, <span><span class=\"nc-purple_bg\">S. gallolyticus</span></span>, <span><span class=\"nc-purple nc-bold\">entérocoques</span></span>, <span><span class=\"nc-purple nc-bold\">HACEK</span></span>) ;</li>\n                <li>ou <span>≥ 1</span> <span>hémoculture</span> ou <span>sérologie</span> positive à <span><span class=\"nc-purple nc-bold\">Coxiella burnetii</span></span> (<span>IgG phase I &gt; 1/800</span>).</li>\n              </ul>\n              <strong><span>Imagerie</span> positive pour <span>les</span> lésions d'EI :</strong>\n              <ul>\n                <li><span><span class=\"nc-blue nc-bold\">échographie cardiaque</span></span> (<span class=\"nc-red_bg\">végétations</span>, <span><span class=\"nc-red_bg\">abcès</span></span>, <span class=\"nc-red_bg\">faux anévrisme</span>, <span class=\"nc-red_bg\">fistule</span>, <span class=\"nc-red_bg\">destruction valvulaire</span>, <span class=\"nc-red_bg\">désinsertion de prothèse</span>) ;</li>\n                <li>ou <span><span class=\"nc-blue nc-bold\">TEP-scan</span></span> / <span><span class=\"nc-blue_bg\">scintigraphie aux leucocytes marqués</span></span> ;</li>\n                <li>ou <span>scanner cardiaque</span> (<span><span class=\"nc-red_bg\">abcès</span></span>, <span class=\"nc-red_bg\">faux anévrisme</span>, <span class=\"nc-red_bg\">fistule</span>).</li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li><span>Terrain</span> : patient à haut risque ou risque intermédiaire d'EI, ou toxicomanie IV ;</li>\n                <li><span>Fièvre</span> ≥ <span>38 °C</span> ;</li>\n                <li><span>Phénomènes vasculaires</span> : embolies artérielles ou pulmonaires, <span class=\"nc-blue_bg\">anévrismes </span><span><span class=\"nc-blue_bg\">infectieux</span></span><span class=\"nc-blue_bg\"> (mycotiques)</span>, <span class=\"nc-blue_bg\">hémorragies</span>, <span class=\"nc-blue_bg\">placards de Janeway</span> ;</li>\n                <li><span>Phénomènes immunologiques</span> : <span class=\"nc-orange_bg\">glomérulonéphrite</span>, <span class=\"nc-orange_bg\">nodosités d'Osler</span>, <span class=\"nc-orange_bg\">taches de Roth</span>, <span class=\"nc-orange_bg\">facteurs rhumatoïdes</span> ;</li>\n                <li><span>Argument microbiologique</span> n'entrant pas dans la définition d'un <span>critère majeur</span> (<span>hémocultures</span>, <span>sérologies</span>).</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Seuils diagnostiques (EI certaine).</strong> <span>2 critères majeurs</span>, ou <span>1 majeur + 3 mineurs</span>, ou <span><span class=\"nc-red_bg nc-bold\">5 critères mineurs</span></span> (à défaut d'un critère histologique). <strong>EI possible</strong> : 1 majeur + 1-<span <span=\"\">&gt;2</span> mineurs, ou 3 mineurs.</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-152.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 152</a></li><li><a href=\"https://www.infectiologie.com/fr/actualites/endocardite-antibiotherapie-position-spilf-aepei-diaporama-du-groupe-reco_-n.html\" target=\"_blank\" rel=\"noopener noreferrer\">SPILF–AEPEI · antibiothérapie et prophylaxie de l’endocardite, 2025</a></li></ul></details>","frequence":1},{"id":"152-11","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les arguments échocardiographiques du diagnostic d'EI","contenu":"<div class=\"notion-course\"><p>L'<span><span class=\"nc-blue nc-bold\">échographie cardiaque</span></span> (<span>ETT</span> puis <span>ETO</span>) recherche <span>les</span> <span>lésions caractéristiques d'EI</span> :</p>\n      <ul>\n        <li><span>Végétations</span> — <span>lésion</span> élémentaire proliférante de l'EI ;</li>\n        <li><span><span class=\"nc-yellow_bg\">Destructions valvulaires</span></span> — perforation, mutilation, <span>rupture</span> de cordage ;</li>\n        <li><span><span class=\"nc-red_bg\">Abcès</span></span> et <span>faux anévrisme</span> ;</li>\n        <li><span>Fistules intracardiaques</span> ;</li>\n        <li><span>Désinsertion de prothèse</span> et <span><span class=\"nc-red nc-bold\">fuite paraprothétique</span></span>.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong><span>Critère de</span> Duke.</strong> Une imagerie positive pour ces lésions est un <span>critère majeur</span> des <span>critères de</span> Duke modifiés (<span>2023</span>), au même titre qu'un <span>TEP-scanner</span> ou une <span><span class=\"nc-blue_bg\">scintigraphie aux leucocytes marqués</span></span> positifs, ou un <span>scanner cardiaque</span> montrant <span><span class=\"nc-red_bg\">abcès</span></span>, <span class=\"nc-red_bg\">faux anévrisme</span> ou <span class=\"nc-red_bg\">fistule</span>.</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-152.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 152</a></li><li><a href=\"https://www.infectiologie.com/fr/actualites/endocardite-antibiotherapie-position-spilf-aepei-diaporama-du-groupe-reco_-n.html\" target=\"_blank\" rel=\"noopener noreferrer\">SPILF–AEPEI · antibiothérapie et prophylaxie de l’endocardite, 2025</a></li></ul></details>","frequence":0},{"id":"152-12","rang":"A","rubrique":"Examens complémentaires","titre":"Savoir hiérarchiser les examens complémentaires en fonction de l'état clinique du patient (hémocultures, échocardiographie, autres examens complémentaires)","contenu":"<div class=\"notion-course\"><p>Le bilan se hiérarchise autour des <strong>deux piliers</strong> — <span><span class=\"nc-yellow_bg nc-bold\">hémocultures</span></span> et <span><span class=\"nc-blue nc-bold\">échographie cardiaque</span></span> — complétés selon l'état clinique du patient.</p>\n      <table>\n        <thead><tr><th>Niveau</th><th>Examens</th></tr></thead>\n        <tbody>\n          <tr><td>Piliers diagnostiques</td><td><strong><span>Hémocultures</span> :</strong> <span>mise en évidence du germe</span><br><strong><span>Échographie cardiaque</span> :</strong> <span>ETT</span> puis <span>ETO</span> — confirme l'atteinte de l'endocarde</td></tr>\n          <tr><td>Si <span>échographie</span> non contributive</td><td><strong><span><span class=\"nc-blue_bg\">TDM</span></span><span class=\"nc-blue_bg\"> cardiaque</span> :</strong> <span><span class=\"nc-orange nc-bold\">abcès</span></span> non vus à l'écho, surtout si prothèse<br><strong><span>TEP-scanner 18-FDG</span> / <span><span class=\"nc-blue_bg\">scintigraphie aux leucocytes marqués</span></span> :</strong> hyperfixation, EI sur prothèse ; dépiste <span>les</span> localisations septiques</td></tr>\n          <tr><td>Biologie</td><td><strong><span><span class=\"nc-blue_bg\">NFS</span></span> :</strong> <span>hyperleucocytose à PNN</span> ; <span>anémie</span> ; <span>thrombopénie</span><br><strong>Inflammation :</strong> <span><span class=\"nc-blue_bg\">CRP</span></span> élevée<br><strong>Retentissement :</strong> <span>ionogramme</span> ; <span><span class=\"nc-blue_bg\">créatininémie</span></span> ; <span>BU</span><br><strong>Immunologie :</strong> <span><span class=\"nc-pink_bg\">facteur rhumatoïde</span></span> ; <span>complément</span> ; <span><span class=\"nc-pink_bg\">cryoglobulinémie</span></span></td></tr>\n          <tr><td>Retentissement cardiaque</td><td><strong><span>ECG</span> :</strong> trouble de conduction (<span><span class=\"nc-red nc-bold\">BAV</span></span>) ; <span><span class=\"nc-red nc-bold\">ischémie myocardique</span></span> (embolie coronarienne)</td></tr>\n          <tr><td>Localisations secondaires</td><td><strong><span><span class=\"nc-blue_bg\">RXT</span></span> :</strong> <span>OAP</span> (EI cœur gauche) ou pneumopathie (EI cœur droit)<br><strong><span><span class=\"nc-yellow_bg\">TDM</span> corps entier injectée</span> :</strong> localisations septiques ; anévrismes mycotiques<br><strong><span>IRM cérébrale</span> :</strong> plus sensible que le <span>scanner</span>, sur point d'appel<br><strong><span>Coronarographie</span>, <span><span class=\"nc-blue_bg\">troponine</span></span> :</strong> si embolie coronarienne suspectée</td></tr>\n        </tbody>\n      </table></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-152.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 152</a></li><li><a href=\"https://www.infectiologie.com/fr/actualites/endocardite-antibiotherapie-position-spilf-aepei-diaporama-du-groupe-reco_-n.html\" target=\"_blank\" rel=\"noopener noreferrer\">SPILF–AEPEI · antibiothérapie et prophylaxie de l’endocardite, 2025</a></li></ul></details>","frequence":2,"liens":[{"href":"https://radiopaedia.org/articles/infective-endocarditis","label":"Radiopaedia : Infective endocarditis"}]},{"id":"152-13","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les principales localisations emboliques en cas d'EI","contenu":"<div class=\"notion-course\"><p><span>Les</span> emboles proviennent des <span>végétations</span> ; leur localisation dépend du côté du cœur atteint.</p>\n      <table>\n        <thead><tr><th>Origine</th><th>Localisations emboliques</th></tr></thead>\n        <tbody>\n          <tr><td>EI du <strong>cœur gauche</strong><br>(emboles systémiques)</td><td><strong>Cérébral :</strong> <span><span class=\"nc-red nc-bold\">AVC</span></span>, <span>AIT</span>, <span>convulsions</span>, <span><span class=\"nc-red nc-bold\">syndrome méningé</span></span> — <span>~25 %</span> des cas, <span>2ᵉ cause de décès</span><br><strong>Viscéral :</strong> <span><span class=\"nc-red nc-bold\">rate</span></span>, <span><span class=\"nc-red nc-bold\">reins</span></span>, <span><span class=\"nc-red nc-bold\">foie</span></span> — <span><span class=\"nc-red nc-bold\">abcès</span></span> ou <span>infarctus</span><br><strong>Ostéo-articulaire :</strong> <span><span class=\"nc-red nc-bold\">arthrite</span></span> ; <span>spondylodiscite</span><br><strong>Membres :</strong> <span>ischémie aiguë</span> ou subaiguë<br><strong>Coronaire :</strong> <span><span class=\"nc-red nc-bold\">ischémie myocardique</span></span></td></tr>\n          <tr><td>EI du <strong>cœur droit</strong></td><td><strong><span class=\"nc-red nc-bold\">Embolies pulmonaires septiques</span> :</strong> fréquemment multiples — <span><span class=\"nc-red nc-bold\">infarctus pulmonaires</span></span>, <span>abcès</span><br><strong>Pneumopathies :</strong> <span>récidivantes</span> et <span>abcédées</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Anévrismes mycotiques.</strong> Anévrismes <span>infectieux</span> de toute localisation — ils exposent à une <span>hémorragie cataclysmique</span> par <span>rupture</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 340 — <span>AVC</span> · 156 — Infection ostéo-articulaire</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-152.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 152</a></li><li><a href=\"https://www.infectiologie.com/fr/actualites/endocardite-antibiotherapie-position-spilf-aepei-diaporama-du-groupe-reco_-n.html\" target=\"_blank\" rel=\"noopener noreferrer\">SPILF–AEPEI · antibiothérapie et prophylaxie de l’endocardite, 2025</a></li></ul></details>","frequence":1},{"id":"152-14","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir quand une antibiothérapie probabiliste est indiquée en cas de suspicion d'EI","contenu":"<div class=\"notion-course\"><p>L'<span>antibiothérapie probabiliste</span> est instaurée <strong>après <span>les</span> <span><span class=\"nc-yellow_bg nc-bold\">hémocultures</span></span></strong> et <strong>avant leur résultat</strong>. Elle n'est justifiée que dans trois situations :</p>\n      <ul>\n        <li><span><span class=\"nc-red nc-bold\">Forte suspicion</span></span> d'EI — surtout si <span>images évocatrices</span> à l'<span><span class=\"nc-blue nc-bold\">échographie cardiaque</span></span> ;</li>\n        <li><span><span class=\"nc-red nc-bold\">Sepsis sévère</span></span> ;</li>\n        <li><span><span class=\"nc-red nc-bold\">Indication chirurgicale urgente</span></span>.</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Règle d'or.</strong> Hors de ces situations, on <strong>attend la <span>documentation microbiologique</span></strong>. Dans tous <span>les</span> cas, les <span><span class=\"nc-yellow_bg nc-bold\">hémocultures</span></span> sont prélevées <em>avant</em> toute <span>antibiothérapie</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 158 — <span>Sepsis</span> et <span>choc septique</span></em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-152.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 152</a></li><li><a href=\"https://www.infectiologie.com/fr/actualites/endocardite-antibiotherapie-position-spilf-aepei-diaporama-du-groupe-reco_-n.html\" target=\"_blank\" rel=\"noopener noreferrer\">SPILF–AEPEI · antibiothérapie et prophylaxie de l’endocardite, 2025</a></li></ul></details>","frequence":0},{"id":"152-15","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes du traitement antibiotique de l'EI","contenu":"<div class=\"notion-course\"><ul><li>Prise en charge initiale hospitalière, équipe multidisciplinaire d’endocardite. Antibiotiques à doses et diffusion adaptées, guidés par espèce, sensibilité, valve native/prothèse et complications.</li><li>Durée souvent quatre à six semaines, mais variable selon agent et situation. La chirurgie ne remet pas systématiquement le compteur à zéro ; microbiologie opératoire et évolution guident la décision.</li><li>Les associations et aminosides ne sont pas <span class=\"nc-yellow_bg nc-bold\">systématiques</span>. Relais oral possible chez certains patients stables et sélectionnés, après évaluation spécialisée ; éviter la règle « tout IV pendant toute la durée ».</li><li>Surveillance clinique, <span class=\"nc-yellow_bg nc-bold\">hémocultures</span>, rein/foie, concentrations si nécessaire et échographie. Trois motifs majeurs de chirurgie : insuffisance cardiaque, infection non contrôlée, prévention embolique ; urgence et risque neurologique discutés en équipe.</li></ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-152.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 152</a></li><li><a href=\"https://www.infectiologie.com/fr/actualites/endocardite-antibiotherapie-position-spilf-aepei-diaporama-du-groupe-reco_-n.html\" target=\"_blank\" rel=\"noopener noreferrer\">SPILF–AEPEI · antibiothérapie et prophylaxie de l’endocardite, 2025</a></li></ul></details>","frequence":0},{"id":"152-16","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités de prise en charge de la porte d'entrée d'une EI","contenu":"<div class=\"notion-course\"><p>Le <strong>traitement de la <span><span class=\"nc-orange_bg\">porte d'entrée</span></span></strong> est indispensable : sans lui, le risque de <span>récidive</span> persiste. Sa recherche et sa prise en charge dépendent du germe identifié.</p>\n      <table>\n        <thead><tr><th>Origine</th><th>Germes</th><th>Prise en charge</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"nc-yellow_bg\">Cutanée</span></td><td><span>S. aureus</span>, staph. à coagulase négative</td><td>Examen du revêtement cutané ; <span>ablation et culture du cathéter</span></td></tr>\n          <tr><td><span class=\"nc-blue_bg\">Bucco-dentaire</span></td><td><span><span class=\"nc-purple_bg\">Streptocoques oraux</span></span>, <span><span class=\"nc-purple_bg\">HACEK</span></span></td><td><span><span class=\"nc-blue_bg\">Panoramique dentaire</span></span> ; consultation et soins stomatologiques</td></tr>\n          <tr><td>Digestive</td><td><span><span class=\"nc-purple_bg\">S. gallolyticus</span></span>, <span><span class=\"nc-purple_bg\">entérocoques</span></span></td><td><span><span class=\"nc-blue_bg\">Coloscopie totale</span></span> ; <span><span class=\"nc-blue_bg\">imagerie abdominale</span></span> et des voies biliaires ; recherche d'une <span>tumeur colique</span></td></tr>\n          <tr><td>Urinaire</td><td><span><span class=\"nc-purple_bg\">Entérocoques</span></span></td><td><span><span class=\"nc-blue_bg\">ECBU</span></span> ; <span>échographie</span> ou <span>scanner</span> des voies urinaires</td></tr>\n        </tbody>\n      </table></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-152.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 152</a></li><li><a href=\"https://www.infectiologie.com/fr/actualites/endocardite-antibiotherapie-position-spilf-aepei-diaporama-du-groupe-reco_-n.html\" target=\"_blank\" rel=\"noopener noreferrer\">SPILF–AEPEI · antibiothérapie et prophylaxie de l’endocardite, 2025</a></li></ul></details>","frequence":1},{"id":"152-17","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes d'éducation à la santé après un épisode d'EI","contenu":"<div class=\"notion-course\"><p>L'éducation à la santé concerne <strong>tous <span>les</span> patients porteurs d'une <span class=\"nc-yellow_bg\">cardiopathie à risque</span></strong><span class=\"nc-yellow_bg\"> d'EI</span> (<span>groupe A</span> ou <span>groupe B</span>). Mesures à connaître :</p>\n      <ul>\n        <li>Maintenir une bonne <strong><span>hygiène <span class=\"nc-blue_bg\">bucco-dentaire</span></span></strong> ;</li>\n        <li><span>Consultation chez le dentiste</span> — <span>2×/an</span> si cardiopathie à haut risque, <span>1×/an</span> pour <span>les</span> autres ;</li>\n        <li><span>Désinfecter les plaies</span> ;</li>\n        <li>Éradiquer <span>les</span> <span>colonisations bactériennes chroniques</span> — cutanées et urinaires ;</li>\n        <li>Traiter <span>les</span> <span>infections bactériennes locales</span> par antibiotiques ;</li>\n        <li><span>Asepsie stricte</span> lors des procédures à risque de <span>bactériémie</span> ;</li>\n        <li>Éviter <span>les</span> effractions cutanées — <span>tatouages</span>, <span>piercings</span> ;</li>\n        <li>Limiter et renouveler <span>les</span> <span>voies veineuses</span> ;</li>\n        <li>Éviter l'<span>automédication par antibiotiques</span> et consulter rapidement en cas de <span>fièvre</span>.</li>\n      </ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-152.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 152</a></li><li><a href=\"https://www.infectiologie.com/fr/actualites/endocardite-antibiotherapie-position-spilf-aepei-diaporama-du-groupe-reco_-n.html\" target=\"_blank\" rel=\"noopener noreferrer\">SPILF–AEPEI · antibiothérapie et prophylaxie de l’endocardite, 2025</a></li></ul></details>","frequence":0},{"id":"152-18","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de l'antibioprophylaxie de l'EI (groupe de cardiopathie à risque, gestes à risque)","contenu":"<div class=\"notion-course\"><ul><li>La prophylaxie dentaire concerne les patients à haut risque et les gestes exposants : manipulation gingivale/périapicale ou effraction muqueuse. Hygiène quotidienne et suivi dentaire restent essentiels.</li><li>Repère adulte sans allergie : <span class=\"nc-pink_bg\">amoxicilline</span> 2 g, 30–60 minutes avant le geste. Enfant : 50 mg/kg, sans dépasser 2 g. Alternatives selon type d’allergie, voie et recommandation française actualisée ; ne pas prescrire une céphalosporine automatiquement après anaphylaxie à pénicilline.</li><li>Ne pas confondre prophylaxie de l’endocardite et antibioprophylaxie propre à une intervention chirurgicale. L’assertion « aucune autre chirurgie ne nécessite de prophylaxie » est fausse.</li><li>Pour les autres procédures, appliquer le cadre SPILF/AEPEI et les recommandations spécifiques ; ne pas extrapoler la liste des gestes dentaires à toute intervention.</li></ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-152.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 152</a></li><li><a href=\"https://www.infectiologie.com/fr/actualites/endocardite-antibiotherapie-position-spilf-aepei-diaporama-du-groupe-reco_-n.html\" target=\"_blank\" rel=\"noopener noreferrer\">SPILF–AEPEI · antibiothérapie et prophylaxie de l’endocardite, 2025</a></li></ul></details>","frequence":2},{"id":"152-19","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les principales complications des EI : complications cardiaques, complications emboliques, complications infectieuses","contenu":"<div class=\"notion-course\"><p><span>Les</span> complications de l'EI se répartissent en trois groupes — c'est le plan même de l'intitulé officiel.</p>\n      <table>\n        <thead><tr><th>Type</th><th>Complications</th></tr></thead>\n        <tbody>\n          <tr><td>Cardiaques</td><td><span class=\"nc-red_bg\">Destruction valvulaire</span> → <span><span class=\"nc-red nc-bold\">régurgitation</span></span> <span class=\"nc-red nc-bold\">valvulaire</span> ou paraprothétique ; <span><span class=\"nc-red nc-bold\">insuffisance cardiaque aiguë</span></span> (<span>OAP</span>, <span>choc cardiogénique</span>) ; <span><span class=\"nc-red_bg\">abcès</span></span> → <span><span class=\"nc-red nc-bold\">BAV</span></span> (<span><span class=\"nc-pink nc-bold\">abcès</span></span><span class=\"nc-pink nc-bold\"> septal</span> des <span class=\"nc-pink nc-bold\">EI aortiques</span>), et par <span>rupture</span> → <span>faux anévrisme</span> ou <span><span class=\"nc-red nc-bold\">fistule intracardiaque</span></span> ; <span><span class=\"nc-red_bg\">désinsertion de prothèse</span></span></td></tr>\n          <tr><td>Emboliques</td><td>Emboles systémiques (cœur gauche) → <span><span class=\"nc-red nc-bold\">AVC</span></span>, <span><span class=\"nc-red nc-bold\">abcès</span></span> spléniques / rénaux / hépatiques ; <span><span class=\"nc-red nc-bold\">embolies pulmonaires septiques</span></span> (cœur droit) ; <span><span class=\"nc-blue_bg\">anévrismes infectieux (mycotiques)</span></span> à risque <span>hémorragique</span></td></tr>\n          <tr><td>Infectieuses</td><td><span>Choc septique</span> ; <span class=\"nc-red nc-bold\">foyers </span><span><span class=\"nc-red nc-bold\">infectieux</span></span><span class=\"nc-red nc-bold\"> à distance</span> — <span><span class=\"nc-red nc-bold\">spondylodiscite</span></span>, <span><span class=\"nc-red nc-bold\">arthrite</span></span>, <span>méningite</span>, <span><span class=\"nc-red nc-bold\">abcès</span></span> ; infection localement non contrôlée</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong><span>Les</span> deux causes de décès.</strong> L'<span><span class=\"nc-red nc-bold\">insuffisance cardiaque</span></span> est la <span>1ʳᵉ</span> cause de <span>mortalité</span> de l'EI, les <span><span class=\"nc-red nc-bold\">emboles cérébraux</span></span> la <span>2ᵉ</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 234 — <span>Insuffisance cardiaque</span> · 340 — <span>AVC</span></em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-152.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 152</a></li><li><a href=\"https://www.infectiologie.com/fr/actualites/endocardite-antibiotherapie-position-spilf-aepei-diaporama-du-groupe-reco_-n.html\" target=\"_blank\" rel=\"noopener noreferrer\">SPILF–AEPEI · antibiothérapie et prophylaxie de l’endocardite, 2025</a></li></ul></details>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong><span class=\"kw-alerte\">Urgence</span> diagnostique et thérapeutique :</strong> <span class=\"kw-def\">mortalité</span> hospitalière <span class=\"kw-chiffre\">15-30 %</span> — 1ʳᵉ cause de décès = <span class=\"kw-etio\">insuffisance cardiaque</span>, 2ᵉ = <span class=\"kw-alerte\">emboles cérébraux</span>.</p><p><strong><span class=\"kw-bio\">Hémocultures</span> AVANT toute <span class=\"kw-ttt\">antibiothérapie</span> :</strong> <span class=\"kw-chiffre\">3 prélèvements</span> sur <span class=\"kw-chiffre\">24 h</span> espacés de <span class=\"kw-chiffre\">≥ 1 h</span> ; en cas de <span class=\"kw-alerte\">sepsis</span>, <span class=\"kw-chiffre\">2-3 hémocultures en &lt; 1 h</span> avant de démarrer l’<span class=\"kw-ttt\">ATB</span> urgente.</p><p><strong>ATB probabiliste urgente</strong> seulement si <span class=\"kw-alerte\">forte suspicion</span> (image à l’<span class=\"kw-imagerie\">écho</span>), <span class=\"kw-alerte\">sepsis sévère</span> ou <span class=\"kw-alerte\">indication chirurgicale urgente</span>.</p><p><strong><span class=\"kw-imagerie\">Échographie</span> :</strong> <span class=\"kw-imagerie\">ETT</span> d’emblée ; si normale mais suspicion forte, répéter <span class=\"kw-imagerie\">ETT + ETO à J7-J10</span>.</p>","hospit":"<p><strong><span class=\"kw-alerte\">Hospitalisation</span> systématique</strong> avec prise en charge multidisciplinaire (« endocarditis team » : cardiologue, infectiologue, chirurgien).</p><p><strong><span class=\"kw-ttt\">Chirurgie</span> cardiaque</strong> indiquée en phase active dans <span class=\"kw-chiffre\">50 %</span> des cas — discuter d’emblée le recours à un centre chirurgical.</p><p><strong>EI sur matériel</strong> (sonde de <span class=\"kw-etio\">stimulateur</span>/<span class=\"kw-etio\">défibrillateur</span>, <span class=\"kw-etio\">cathéter veineux central</span>, EI du cœur droit) : <span class=\"kw-ttt\">retrait du matériel</span> en plus des antibiotiques.</p><p><strong>Avant toute chirurgie valvulaire :</strong> <span class=\"kw-imagerie\">imagerie cérébrale</span> — une <span class=\"kw-alerte\">complication neurologique</span> peut contre-indiquer temporairement la circulation extracorporelle.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Insuffisance cardiaque aiguë fébrile</span> — <span class=\"kw-clinique\">OAP</span>, <span class=\"kw-alerte\">choc cardiogénique</span> (1ʳᵉ cause de décès)</li><li><span class=\"kw-alerte\">Régurgitation valvulaire aiguë</span> ou désinsertion de prothèse</li><li><span class=\"kw-alerte\">BAV</span> par <span class=\"kw-clinique\">abcès</span> septal (surtout EI aortique) → <span class=\"kw-clinique\">syncope</span>, <span class=\"kw-clinique\">lipothymie</span></li><li><span class=\"kw-alerte\">Sepsis sévère</span> / <span class=\"kw-alerte\">choc septique</span></li><li>Embole cérébral : <span class=\"kw-etio\">AVC</span>, <span class=\"kw-clinique\">syndrome méningé</span>, <span class=\"kw-clinique\">troubles de la conscience</span> (2ᵉ cause de décès)</li><li><span class=\"kw-alerte\">Anévrisme mycotique</span> — risque d’<span class=\"kw-alerte\">hémorragie cataclysmique</span> par <span class=\"kw-alerte\">rupture</span></li><li><span class=\"kw-clinique\">Végétation du cœur gauche</span> <span class=\"kw-chiffre\">&gt; 10 mm</span> (risque <span class=\"kw-etio\">embolique</span>)</li><li>EI <span class=\"kw-etio\">fongique</span> ou à <span class=\"kw-etio\">germes multirésistants</span></li><li><span class=\"kw-alerte\">Hémocultures positives persistantes</span> malgré <span class=\"kw-chiffre\">&gt; 7 jours</span> d’<span class=\"kw-ttt\">ATB</span></li><li><span class=\"kw-def\">Terrain</span> de mauvais <span class=\"kw-def\">pronostic</span> : <span class=\"kw-etio\">S. aureus</span>, EI sur <span class=\"kw-etio\">prothèse</span>, <span class=\"kw-imagerie\">abcès intracardiaque</span>, <span class=\"kw-imagerie\">végétation volumineuse</span></li></ul>","principes":"<p><strong><span class=\"kw-ttt\">Antibiothérapie</span> :</strong> <span class=\"kw-ttt\">bactéricide</span>, molécules <span class=\"kw-ttt\">synergiques</span>, fortes doses, voie <span class=\"kw-ttt\">IV</span>, <span class=\"kw-chiffre\">4 à 6 semaines</span> — durée non modifiée même si une <span class=\"kw-ttt\">chirurgie</span> est nécessaire.<br><strong>ATB probabiliste</strong> uniquement si <span class=\"kw-alerte\">forte suspicion</span> (image écho), <span class=\"kw-alerte\">sepsis sévère</span> ou <span class=\"kw-alerte\">indication chirurgicale urgente</span>, toujours <em>après</em> <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">hémocultures</span> et avant leur résultat.<br><strong>Toujours :</strong> <span class=\"kw-ttt\">traitement de la porte d’entrée</span> + prise en charge multidisciplinaire.</p><p><strong>ATB probabiliste — valve native ou prothèse &gt;<span class=\"kw-chiffre\"> 1 an</span></strong></p><ul><li><span class=\"kw-ttt\">Amoxicilline</span> + <span class=\"kw-ttt\">ceftriaxone</span> (ou <span class=\"kw-ttt\">oxacilline</span>) + <span class=\"kw-ttt\">gentamicine</span></li><li>Si <span class=\"kw-ci\">allergie aux pénicillines</span> : <span class=\"kw-ttt\">céfazoline</span> ou <span class=\"kw-ttt\">vancomycine</span> + <span class=\"kw-ttt\">gentamicine</span></li></ul><p><strong>ATB probabiliste — prothèse &lt;<span class=\"kw-chiffre\"> 1 an</span> ou EI non communautaire</strong></p><ul><li>Ne pas passer à côté d’un <span class=\"kw-etio\">SARM</span> : <span class=\"kw-ttt\">vancomycine</span> (ou <span class=\"kw-ttt\">daptomycine</span>) + <span class=\"kw-ttt\">gentamicine</span> + <span class=\"kw-ttt\">rifampicine</span></li><li><span class=\"kw-ttt\">Gentamicine</span> ≤ <span class=\"kw-chiffre\">15 jours</span> — <span class=\"kw-ci\">néphrotoxicité des aminosides</span></li></ul><p><strong><span class=\"kw-ttt\">Chirurgie</span> en phase active (<span class=\"kw-chiffre\">50 %</span> des cas)</strong></p><ul><li><strong>Hémodynamique :</strong> <span class=\"kw-alerte\">IC gauche réfractaire</span>, <span class=\"kw-alerte\">choc cardiogénique</span>, <span class=\"kw-alerte\">régurgitation aiguë</span> mal tolérée</li><li><strong>Infectieuse :</strong> <span class=\"kw-alerte\">infection non contrôlée</span> (<span class=\"kw-clinique\">abcès</span>, fistule, faux anévrisme, désinsertion, <span class=\"kw-alerte\">BAV</span>), EI <span class=\"kw-etio\">fongique</span>/<span class=\"kw-etio\">multirésistante</span>, <span class=\"kw-bio\">hémocultures</span> + malgré <span class=\"kw-chiffre\">&gt; 7 j</span> d’ATB</li><li><strong><span class=\"kw-etio\">Embolique</span> :</strong> <span class=\"kw-clinique\">végétation cœur gauche</span> <span class=\"kw-chiffre\">&gt; 10 mm</span> persistante après embolie ou associée à une autre indication</li><li><span class=\"kw-ci\">Complication neurologique</span> = <span class=\"kw-ci\">contre-indication</span> temporaire à la circulation extracorporelle (imagerie cérébrale préalable)</li></ul><p><strong>Mesures associées</strong></p><ul><li><span class=\"kw-ttt\">Traitement de la porte d’entrée</span> (sinon récidive) : soins dentaires, ablation/culture du <span class=\"kw-etio\">cathéter</span>, <span class=\"kw-imagerie\">coloscopie</span>, <span class=\"kw-bio\">ECBU</span>…</li><li>Traitement médical de l’<span class=\"kw-etio\">insuffisance cardiaque</span> ; <span class=\"kw-ttt\">retrait du matériel</span> (sonde, cathéter) si EI sur matériel</li><li><span class=\"kw-ci\">Pas d’antiagrégant ni d’anticoagulant curatif</span> (risque <span class=\"kw-etio\">hémorragique</span>, anévrisme mycotique) ; <span class=\"kw-ttt\">anticoagulation</span> préventive autorisée</li></ul><p><strong><span class=\"kw-def\">Prévention secondaire</span></strong></p><ul><li><strong>Éducation (groupe A et B) :</strong> <span class=\"kw-clinique\">hygiène bucco-dentaire</span>, dentiste <span class=\"kw-chiffre\">2×/an</span> (haut risque) ou <span class=\"kw-chiffre\">1×/an</span>, désinfection des plaies, <span class=\"kw-ci\">éviter tatouages/piercings</span> et <span class=\"kw-ci\">automédication antibiotique</span></li><li><strong><span class=\"kw-ttt\">Antibioprophylaxie</span> (groupe A seul + geste dentaire à risque) :</strong> <span class=\"kw-ttt\">amoxicilline</span> <span class=\"kw-chiffre\">2 g</span> <span class=\"kw-chiffre\">30-60 min avant</span> ; si <span class=\"kw-ci\">allergie</span> : <span class=\"kw-ttt\">céfalexine</span>/<span class=\"kw-ttt\">azithromycine</span>/<span class=\"kw-ttt\">doxycycline</span></li><li><span class=\"kw-ci\">Pas d’antibioprophylaxie</span> avant <span class=\"kw-imagerie\">coloscopie</span>, <span class=\"kw-ttt\">intubation</span> ou autre <span class=\"kw-ttt\">chirurgie</span></li></ul>","suivi":"<p><strong>Efficacité :</strong> régression de la <span class=\"kw-clinique\">fièvre</span> et du <span class=\"kw-bio\">syndrome inflammatoire</span> (<span class=\"kw-bio\">CRP</span>) ; <span class=\"kw-bio\">hémocultures quotidiennes</span> jusqu’à stérilisation ; <span class=\"kw-clinique\">évolution</span> favorable à l’<span class=\"kw-imagerie\">écho</span> (<span class=\"kw-imagerie\">ETT</span>/<span class=\"kw-imagerie\">ETO</span> répétées).<br><strong>Tolérance :</strong> doses adaptées aux fonctions rénale/hépatique ; <span class=\"kw-bio\">dosages plasmatiques</span> des <span class=\"kw-ttt\">aminosides</span> et de la <span class=\"kw-ttt\">vancomycine</span> ; <span class=\"kw-bio\">créatininémie</span> (<span class=\"kw-ci\">néphrotoxicité gentamicine/vancomycine</span>).<br><strong>EI aortique :</strong> <span class=\"kw-bio\">ECG quotidien</span> — dépister un <span class=\"kw-alerte\">BAV</span> par <span class=\"kw-clinique\">abcès</span> septal.<br><strong>Guérison :</strong> seule l’<span class=\"kw-alerte\">absence de rechute</span> après arrêt de l’ATB l’affirme ; négativation des <span class=\"kw-bio\">hémocultures</span>, disparition de la <span class=\"kw-clinique\">fièvre</span> et du <span class=\"kw-clinique\">souffle</span> ne suffisent pas seules.</p><p><strong>Complications à dépister</strong></p><ul><li><strong>Cardiaques :</strong> <span class=\"kw-alerte\">régurgitation</span>, <span class=\"kw-alerte\">insuffisance cardiaque aiguë</span>, <span class=\"kw-clinique\">abcès</span> → <span class=\"kw-alerte\">BAV</span>, faux anévrisme, <span class=\"kw-clinique\">fistule</span>, désinsertion de prothèse</li><li><strong>Emboliques :</strong> <span class=\"kw-etio\">AVC</span>, <span class=\"kw-clinique\">abcès</span> spléniques/rénaux/hépatiques, <span class=\"kw-clinique\">embolies pulmonaires septiques</span> (cœur droit), <span class=\"kw-alerte\">anévrismes mycotiques</span></li><li><strong>Infectieuses :</strong> <span class=\"kw-alerte\">choc septique</span>, <span class=\"kw-clinique\">spondylodiscite</span>, <span class=\"kw-clinique\">arthrite</span>, <span class=\"kw-clinique\">méningite</span>, foyers <span class=\"kw-etio\">infectieux</span> non contrôlés</li></ul>"},"liensGlobaux":[{"href":"https://www.sfcardio.fr/page/chapitre-9-item-152-endocardite-infectieuse","label":"Collège SFC — Endocardite infectieuse (chap. 9, item 152)"},{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-152.pdf","label":"Collège Pilly — Endocardite (item 152, PDF)"},{"href":"https://www.ce-mir.fr/sites/www.ce-mir.fr/files/medias/documents/49.%20Endocardite%20infectieuse.pdf","label":"Collège CE-MIR — Endocardite infectieuse (PDF)"},{"href":"https://fr.wikipedia.org/wiki/Hypertension_art%C3%A9rielle_pulmonaire","label":"Wikipedia — Hypertension artérielle pulmonaire"},{"href":"https://fr.wikipedia.org/wiki/Syndrome_d%27Eisenmenger","label":"Wikipedia — Syndrome d'Eisenmenger"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Suspicion d’endocardite infectieuse — Fièvre + cardiopathie à risque, souffle, accident embolique, purpura ou lombalgie — 1er temps systématique : 3 hémocultures (avant ATB) + ETT","detail":"<h4>CAT — suspicion d’<span class=\"kw-clinique\">endocardite</span> infectieuse — Démarche diagnostique : <span class=\"kw-bio\">hémocultures</span> + <span class=\"kw-imagerie\">échographie</span>, <span class=\"kw-def\">critères de</span> Duke 2023</h4>","branches":[{"to":"q-urgence","label":"Sepsis sévère, choc ou insuffisance cardiaque aiguë mal tolérée","color":"red"},{"to":"q-hemoc","label":"Patient stable → documenter avant de traiter","color":"green"}]},{"id":"q-urgence","kind":"decision","label":"Conduite en urgence — Traitement après les hémocultures, avant leur résultat","branches":[{"to":"t-atb-urg","label":"Forte suspicion (image écho) ou sepsis sévère","color":"red"},{"to":"t-chir-urg","label":"Indication chirurgicale urgente (IC réfractaire, infection non contrôlée)","color":"red"}]},{"id":"t-atb-urg","kind":"terminal","label":"Antibiothérapie probabiliste IV urgente","color":"red","detail":"<h4>Indication</h4><ul><li><span class=\"kw-alerte\">Forte suspicion</span> (image évocatrice à l’<span class=\"kw-imagerie\">écho</span>), <span class=\"kw-alerte\">sepsis sévère</span> ou <span class=\"kw-alerte\">indication chirurgicale urgente</span> — après <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">hémocultures</span>, avant leur résultat.</li></ul><h4>Valve native ou prothèse &gt;<span class=\"kw-chiffre\"> 1 an</span></h4><ul><li><span class=\"kw-ttt\">Amoxicilline</span> + <span class=\"kw-ttt\">ceftriaxone</span> (ou <span class=\"kw-ttt\">oxacilline</span>) + <span class=\"kw-ttt\">gentamicine</span></li><li>Si <span class=\"kw-ci\">allergie aux pénicillines</span> : <span class=\"kw-ttt\">céfazoline</span> ou <span class=\"kw-ttt\">vancomycine</span> + <span class=\"kw-ttt\">gentamicine</span></li></ul><h4>Prothèse &lt;<span class=\"kw-chiffre\"> 1 an</span> ou EI non communautaire</h4><ul><li>Couvrir le <span class=\"kw-etio\">SARM</span> : <span class=\"kw-ttt\">vancomycine</span> (ou <span class=\"kw-ttt\">daptomycine</span>) + <span class=\"kw-ttt\">gentamicine</span> + <span class=\"kw-ttt\">rifampicine</span>.</li></ul><h4>Modalités</h4><ul><li><span class=\"kw-ttt\">Bactéricide</span>, synergique, <span class=\"kw-ttt\">IV</span>, <span class=\"kw-chiffre\">4 à 6 semaines</span> ; <span class=\"kw-ttt\">gentamicine</span> ≤ <span class=\"kw-chiffre\">15 jours</span> (<span class=\"kw-ci\">néphrotoxicité des aminosides</span>).</li></ul>"},{"id":"t-chir-urg","kind":"terminal","label":"Chirurgie cardiaque en phase active","color":"red","detail":"<h4>Hémodynamique</h4><ul><li><span class=\"kw-alerte\">Insuffisance cardiaque gauche réfractaire</span> ou <span class=\"kw-alerte\">choc cardiogénique</span></li><li><span class=\"kw-alerte\">Régurgitation aiguë</span> ou signe échographique de mauvaise tolérance</li></ul><h4>Infectieuse</h4><ul><li><span class=\"kw-alerte\">Infection non contrôlée localement</span> : <span class=\"kw-clinique\">abcès</span>, fistule, faux anévrisme, végétation croissante, désinsertion de prothèse, <span class=\"kw-alerte\">BAV</span></li><li>EI <span class=\"kw-etio\">fongique</span> ou à <span class=\"kw-etio\">germes multirésistants</span></li><li><span class=\"kw-bio\">Hémocultures</span> positives malgré <span class=\"kw-chiffre\">&gt; 7 jours</span> d’<span class=\"kw-ttt\">ATB</span></li></ul><h4><span class=\"kw-etio\">Embolique</span></h4><ul><li><span class=\"kw-clinique\">Végétation du cœur gauche</span> <span class=\"kw-chiffre\">&gt; 10 mm</span> persistante après embolie malgré ATB adaptée, ou associée à une autre indication chirurgicale.</li></ul><h4>Geste</h4><ul><li>Débridement des tissus infectés puis <span class=\"kw-ttt\">plastie</span> ou <span class=\"kw-ttt\">remplacement valvulaire</span>. <span class=\"kw-ci\">Imagerie cérébrale avant toute chirurgie</span> : une complication neurologique contre-indique temporairement la circulation extracorporelle.</li></ul>"},{"id":"q-hemoc","kind":"decision","label":"Hémocultures (positives dans 90 % des cas) — 3 prélèvements / 24 h, espacés ≥ 1 h, sur ponctions distinctes","branches":[{"to":"q-echo","label":"Positives à germe typique d’EI","color":"amber"},{"to":"t-hemoc-neg","label":"Négatives (≈ 10 % des EI)","color":"blue"}]},{"id":"q-echo","kind":"decision","label":"Échographie cardiaque : ETT puis ETO — ETO si ETT positive, ETT négative avec suspicion forte, ou matériel intracardiaque","branches":[{"to":"t-ei-certaine","label":"Lésion caractéristique d’EI (végétation, abcès, fistule…)","color":"amber"},{"to":"t-repeat","label":"Écho normale malgré suspicion forte","color":"blue"}]},{"id":"t-ei-certaine","kind":"terminal","label":"EI certaine (critères de Duke 2023)","color":"amber","detail":"<h4>Diagnostic</h4><ul><li>EI certaine si <span class=\"kw-chiffre\">2 critères majeurs</span>, ou <span class=\"kw-chiffre\">1 majeur + 3 mineurs</span>, ou <span class=\"kw-chiffre\">5 mineurs</span>. Majeurs = <span class=\"kw-bio\">hémocultures typiques</span> + <span class=\"kw-imagerie\">imagerie positive</span> (végétation, <span class=\"kw-clinique\">abcès</span>, fistule…).</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Antibiothérapie documentée</span> : <span class=\"kw-ttt\">bactéricide</span>, synergique, <span class=\"kw-ttt\">IV</span>, <span class=\"kw-chiffre\">4 à 6 semaines</span>, adaptée au germe et à la valve</li><li><span class=\"kw-ttt\">Traitement de la porte d’entrée</span> indispensable (sinon récidive)</li><li>Discuter une <span class=\"kw-ttt\">chirurgie</span> selon <span class=\"kw-clinique\">les</span> indications hémodynamiques / infectieuses / emboliques</li></ul><h4>Bilan d’extension</h4><ul><li><span class=\"kw-imagerie\">TDM corps entier injectée</span> (localisations septiques, anévrismes mycotiques), <span class=\"kw-imagerie\">IRM cérébrale</span> sur point d’appel, <span class=\"kw-bio\">ECG</span> (recherche de <span class=\"kw-alerte\">BAV</span>).</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Régression <span class=\"kw-clinique\">fièvre</span> / <span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">stérilisation des hémocultures</span>, <span class=\"kw-bio\">dosages</span> des <span class=\"kw-ttt\">aminosides</span>/<span class=\"kw-ttt\">vancomycine</span> ; guérison = <span class=\"kw-alerte\">absence de rechute</span> après arrêt.</li></ul>"},{"id":"t-repeat","kind":"terminal","label":"Écho normale : ne pas exclure l’EI","color":"blue","detail":"<h4>Conduite</h4><ul><li>Une <span class=\"kw-imagerie\">échographie normale n’élimine pas</span> le diagnostic : compléter par l’<span class=\"kw-imagerie\">ETO</span> (Se <span class=\"kw-chiffre\">≥ 90 %</span>) et répéter <span class=\"kw-imagerie\">ETT + ETO à J7-J10</span> si la suspicion persiste.</li></ul><h4>Imagerie de <span class=\"kw-chiffre\">2e ligne</span></h4><ul><li><span class=\"kw-imagerie\">TDM cardiaque</span> : <span class=\"kw-clinique\">abcès</span> non vus à l’écho (surtout sur prothèse)</li><li><span class=\"kw-imagerie\">TEP-scanner 18-FDG</span> ou <span class=\"kw-imagerie\">scintigraphie aux leucocytes marqués</span> (EI sur prothèse ; non interprétable <span class=\"kw-chiffre\">&lt; 3 mois</span> après <span class=\"kw-ttt\">chirurgie</span> valvulaire)</li></ul><h4>Microbiologie</h4><ul><li>Poursuivre <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">hémocultures</span> ; si elles restent stériles, dérouler la démarche « <span class=\"kw-bio\">hémocultures négatives</span> ».</li></ul>"},{"id":"t-hemoc-neg","kind":"terminal","label":"EI à hémocultures négatives","color":"blue","detail":"<h4>Causes</h4><ul><li><span class=\"kw-alerte\">ATB préalable</span> aux <span class=\"kw-bio\">hémocultures</span></li><li>Croissance lente : <span class=\"kw-etio\">streptocoques déficients</span>, <span class=\"kw-etio\">HACEK</span>, <span class=\"kw-etio\">Brucella</span>, <span class=\"kw-etio\">champignons</span></li><li>Intracellulaires : <span class=\"kw-etio\">Coxiella burnetii</span>, <span class=\"kw-etio\">Bartonella</span>, <span class=\"kw-etio\">Chlamydia</span>, <span class=\"kw-etio\">Tropheryma whipplei</span>, <span class=\"kw-etio\">Mycoplasma</span>, <span class=\"kw-etio\">Legionella</span></li></ul><h4>Conduite</h4><ul><li>Si <span class=\"kw-alerte\">ATB préalable</span> : <span class=\"kw-ttt\">interrompre</span>, attendre <span class=\"kw-chiffre\">≥ 72 h</span>, répéter <span class=\"kw-chiffre\">3 hémocultures</span> / <span class=\"kw-chiffre\">24 h</span> (sauf traitement urgent indispensable : végétation, <span class=\"kw-clinique\">abcès</span>, <span class=\"kw-alerte\">sepsis</span>)</li><li>Sinon : <span class=\"kw-bio\">techniques spéciales d’hémoculture</span>, <span class=\"kw-bio\">sérologies Coxiella / Bartonella</span>, <span class=\"kw-bio\">PCR</span></li><li>Si opéré : <span class=\"kw-bio\">histologie</span>, <span class=\"kw-bio\">culture</span> ± <span class=\"kw-bio\">PCR</span> de la pièce</li></ul><h4>Distracteurs</h4><ul><li>Ni la <span class=\"kw-etio\">maladie de Lyme</span> ni la <span class=\"kw-etio\">tuberculose</span> ne donnent d’<span class=\"kw-clinique\">endocardite</span>.</li></ul>"}]},"cards":[{"i":"123427253183","n":152,"o":"152-1","u":"Définition","t":"Connaître la définition d'une endocardite infectieuse (EI)","q":"Quelles structures cardiaques sont le plus souvent affectées par une endocardite infectieuse (EI) ?","a":"<div class=\"notion-course\"><p>L'endocardite infectieuse (EI) touche le plus souvent <strong>une ou plusieurs valves cardiaques natives</strong>. Elle peut aussi intéresser l'endocarde pariétal ou tout <span class=\"nc-red nc-bold\">matériel intracardiaque</span> implanté.</p></div>"},{"i":"16a0fb99d528","n":152,"o":"152-1","u":"Définition","t":"Connaître la définition d'une endocardite infectieuse (EI)","q":"Quelles valves cardiaques sont les plus fréquemment atteintes lors d'une endocardite infectieuse (EI) ?","a":"<div class=\"notion-course\"><p>Les valves du <strong>cœur gauche</strong> (mitrale, aortique) sont plus souvent touchées que celles du cœur droit.</p></div>"},{"i":"5affb602df53","n":152,"o":"152-1","u":"Définition","t":"Connaître la définition d'une endocardite infectieuse (EI)","q":"Quels sont les différents types de matériaux intracardiaques qui peuvent être infectés au cours d'une endocardite infectieuse (EI) ?","a":"<div class=\"notion-course\"><ul><li><strong><span class=\"nc-red_bg\">Prothèses valvulaires</span></strong></li><li>Sondes de stimulateur ou de défibrillateur</li><li>Assistances ventriculaires</li><li>Cathéters veineux centraux</li></ul></div>"},{"i":"fe482713c2e0","n":152,"o":"152-1","u":"Définition","t":"Connaître la définition d'une endocardite infectieuse (EI)","q":"Quelle est la définition d'une endocardite infectieuse (EI) ?","a":"<div class=\"notion-course\"><p>L'endocardite infectieuse (EI) est une <strong>infection de l'endocarde</strong>.</p></div>"},{"i":"713e3289e064","n":152,"o":"152-2","u":"Epidémiologie","t":"Connaître l'épidémiologie de l'EI","q":"Quels sont les points essentiels concernant l'épidémiologie de l'EI ?","a":"<div class=\"notion-course\"><p>L'<span><span class=\"nc-red nc-bold\">incidence</span></span><span class=\"nc-red nc-bold\"> de l'EI </span><span><span class=\"nc-red nc-bold\">n'a pas diminué</span></span> ces dernières décennies, mais le <strong>profil des patients</strong> et la répartition des micro-organismes se sont modifiés : <span>vieillissement de la population</span>, progrès médicaux, <span>régression des valvulopathies post-rhumatismales</span>.</p>\n      <p><span>Les</span> patients atteints sont désormais plus âgés et/ou exposés par d'autres situations :</p>\n      <ul>\n        <li><span><span class=\"nc-brown_bg\">Valvulopathies dégénératives</span></span> — fibrose, prolapsus mitral ;</li>\n        <li><span><span class=\"nc-brown_bg\">Toxicomanie intraveineuse</span></span> ;</li>\n        <li><span>Procédures de soins à risque</span> — circulation extracorporelle, cathéters veineux, hémodialyse, stimulateur/<span>défibrillateur</span>, chambre implantable.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Bascule microbiologique.</strong> Autrefois <span>les</span> <span><span class=\"nc-purple nc-bold\">streptocoques oraux</span></span> étaient majoritaires ; aujourd'hui le premier germe est le <span>staphylocoque</span>.</div>\n      <table>\n        <thead><tr><th>Donnée</th><th>Repère EDN</th></tr></thead>\n        <tbody>\n          <tr><td>Sex-ratio</td><td>Prédominance <strong>masculine</strong></td></tr>\n          <tr><td>Âge</td><td>Âge moyen <span>62 ans</span> ; plus fréquente <span class=\"nc-pink nc-bold\">après </span><span><span class=\"nc-pink nc-bold\">70 ans</span></span></td></tr>\n          <tr><td><span>Mortalité</span> hospitalière</td><td><span>15-30 %</span><br>1ʳᵉ cause de décès : <span>insuffisance cardiaque</span><br>2ᵉ cause : <span><span class=\"nc-red nc-bold\">emboles cérébraux</span></span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Facteurs de mauvais <span>pronostic</span></strong> :</p>\n      <ul>\n        <li><span><span class=\"nc-red nc-bold\">Insuffisance cardiaque aiguë</span></span>, <span><span class=\"nc-red nc-bold\">complications neurologiques</span></span>, <span><span class=\"nc-red nc-bold\">syndrome infectieux mal maîtrisé</span></span>, <span><span class=\"nc-red nc-bold\">abcès intracardiaques</span></span>, <span><span class=\"nc-red nc-bold\">végétations volumineuses</span></span> ;</li>\n        <li>EI sur <strong>prothèse</strong> ;</li>\n        <li>Micro-organismes très virulents — <span><span class=\"nc-red nc-bold\">Staphylococcus aureus</span></span> et <span><span class=\"nc-red nc-bold\">champignons</span></span> ;</li>\n        <li><span>Terrain</span> fragile — <span><span class=\"nc-red nc-bold\">âge avancé</span></span>, <span><span class=\"nc-red nc-bold\">diabète</span></span>, <span><span class=\"nc-red nc-bold\">immunodépression</span></span>, insuffisances cardiaque / rénale / respiratoire.</li>\n      </ul></div>"},{"i":"1322b82d4fc9","n":152,"o":"152-3","u":"Epidémiologie","t":"Connaître les situations à risque d'EI (cardiopathie du groupe A, présence de matériel intra-cardiaque, bactériémie à cocci Gram positif)","q":"Quels sont les points essentiels concernant les situations à risque d'EI (cardiopathie du groupe A, présence de matériel intra-cardiaque, bactériémie à cocci Gram positif) ?","a":"<div class=\"notion-course\"><ul><li>Haut risque : antécédent d’endocardite, prothèse valvulaire (TAVI compris), matériel de réparation valvulaire, certaines cardiopathies congénitales cyanogènes ou réparées avec matériel, selon délai et lésion résiduelle. Les assistances ventriculaires relèvent d’un cadre spécialisé.</li><li>Ne pas classer automatiquement un filtre cave, un stent ou toute prothèse vasculaire dans le groupe ouvrant droit à prophylaxie dentaire. Un stimulateur/défibrillateur expose à l’infection de matériel mais n’équivaut pas à une prothèse valvulaire.</li><li>Une bactériémie à S. aureus, <span class=\"nc-green_bg\">entérocoque</span> ou certains <span class=\"nc-purple_bg nc-bold\">streptocoques</span> fait rechercher une endocardite selon contexte. L’absence de cardiopathie connue ne l’exclut pas.</li></ul></div>"},{"i":"0b97f3cf51a9","n":152,"o":"152-4","u":"Étiologies","t":"Connaître les principaux agents infectieux à l'origine d'EI (bactéries, levures)","q":"Quels sont les points essentiels concernant les principaux agents infectieux à l'origine d'EI (bactéries, levures) ?","a":"<div class=\"notion-course\"><p>Le micro-organisme en cause est une <span>bactérie</span> ou, plus rarement, un <span>champignon</span> (levure). <strong><span>Staphylocoques</span>, <span class=\"nc-purple_bg nc-bold\">streptocoques</span> et <span>entérocoques</span></strong> représentent à eux seuls <span>~80 %</span> des EI.</p>\n      <table>\n        <thead><tr><th>Agent <span>infectieux</span></th><th>Fréquence</th><th>Particularité EDN</th></tr></thead>\n        <tbody>\n          <tr><td><span>Staphylococcus aureus</span><br>CG+ en amas</td><td><span>30 %</span></td><td><span>1ᵉʳ germe</span> ; EI <span>les</span> plus graves</td></tr>\n          <tr><td><span>Streptocoques oraux</span><br>CG+ en <span class=\"nc-blue\">chaînette</span> (S. sanguis, mitis, salivarius, mutans)</td><td><span>20 %</span></td><td><span><span class=\"nc-orange_bg\">Porte d'entrée</span></span> <span><span class=\"nc-blue_bg\">bucco-dentaire</span></span></td></tr>\n          <tr><td><span>Streptocoques du groupe D</span><br>S. gallolyticus (bovis)</td><td><span>13 %</span></td><td>Imposent la recherche d'un <span>cancer colique</span></td></tr>\n          <tr><td><span>Staphylocoques à coagulase négative</span><br>S. epidermidis, S. lugdunensis</td><td><span>10 %</span></td><td>Fréquence <span>en augmentation</span>, surtout EI sur prothèse</td></tr>\n          <tr><td><span>Entérocoques</span><br>E. faecalis, E. faecium</td><td><span>10 %</span></td><td><span><span class=\"nc-orange_bg\">Porte d'entrée</span></span> <span><span class=\"nc-red_bg\">digestive</span></span> et <span><span class=\"nc-purple_bg\">urinaire</span></span></td></tr>\n          <tr><td>Groupe <span>HACEK</span><br><em><span>Haemophilus</span>, Aggregatibacter, Cardiobacterium, Eikenella, Kingella</em></td><td><span>5 %</span></td><td>Croissance lente — <span>hémocultures</span> parfois négatives</td></tr>\n          <tr><td><span><span class=\"nc-purple nc-bold\">Candida</span></span> et autres champignons (levures)</td><td><span>&lt; 5 %</span></td><td>EI fongiques — <span>pronostic sévère</span></td></tr>\n          <tr><td>Autres — <span><span class=\"nc-purple nc-bold\">Coxiella burnetii</span></span>, <span class=\"nc-purple nc-bold\">Bartonella</span>, <span class=\"nc-purple nc-bold\">Brucella</span>, <span><span class=\"nc-purple nc-bold\">Chlamydia</span></span>, <span class=\"nc-purple nc-bold\">Tropheryma whipplei</span></td><td><span>&lt; 5 %</span></td><td>EI à <span>hémocultures négatives</span></td></tr>\n          <tr><td>Aucun germe retrouvé malgré le bilan</td><td><span>5-10 %</span></td><td>EI à <span>hémocultures négatives</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 301 — Tumeur colon - rectum</em></p></div>"},{"i":"40a341b49ef2","n":152,"o":"152-5","u":"Physiopathologie","t":"Connaître les portes d'entrée en fonction de l'agent infectieux","q":"Quels sont les points essentiels concernant les portes d'entrée en fonction de l'agent infectieux ?","a":"<div class=\"notion-course\"><p>La <span><span class=\"nc-orange_bg\">porte d'entrée</span></span> est le site <span>infectieux</span> d'où part la <span>bactériémie</span>. Elle <strong>dépend du micro-organisme</strong>, oriente le bilan, mais n'est identifiée que dans <span>~50 %</span> des cas.</p>\n      <table>\n        <thead><tr><th>Agent</th><th><span><span class=\"nc-orange_bg\">Porte d'entrée</span></span></th><th>Bilan orienté</th></tr></thead>\n        <tbody>\n          <tr><td><span><span class=\"nc-purple nc-bold\">S. aureus</span></span>, staph. à coagulase négative, <span>Candida</span></td><td><strong><span class=\"nc-yellow_bg\">Cutanée</span></strong> — plaies, cathéters veineux ou de dialyse, toxicomanie IV, geste peropératoire, stimulateur/<span>défibrillateur</span></td><td><span>Culture du cathéter</span> ; <span>hémocultures</span></td></tr>\n          <tr><td><span><span class=\"nc-purple_bg\">Streptocoques oraux</span></span>, <span class=\"nc-orange_bg\">groupe </span><span><span class=\"nc-orange_bg\">HACEK</span></span></td><td><strong><span class=\"nc-blue_bg\">Bucco-dentaire</span></strong></td><td><span><span class=\"nc-blue_bg\">Panoramique dentaire</span></span> ; consultation stomatologique</td></tr>\n          <tr><td><span><span class=\"nc-purple nc-bold\">Streptocoques du groupe D</span></span> (<span class=\"nc-purple_bg\">S. gallolyticus</span>)</td><td><strong><span class=\"nc-red_bg\">Digestive</span></strong> — cancer, polypes, diverticules coliques</td><td><span><span class=\"nc-blue nc-bold\">Coloscopie</span> systématique</span></td></tr>\n          <tr><td><span><span class=\"nc-purple_bg\">Entérocoques</span></span></td><td><strong>Digestive</strong> et <strong>urinaire</strong></td><td><span><span class=\"nc-blue nc-bold\">ECBU</span></span> ; <span><span class=\"nc-blue nc-bold\">écho abdomino-pelvienne</span></span> ; ± <span><span class=\"nc-blue nc-bold\">coloscopie</span></span></td></tr>\n        </tbody>\n      </table></div>"},{"i":"592820742273","n":152,"o":"152-6","u":"Physiopathologie","t":"Connaître les cardiopathies à risque d'EI du groupe B","q":"Quels sont les points essentiels concernant les cardiopathies à risque d'EI du groupe B ?","a":"<div class=\"notion-course\"><p>Le <span>groupe B</span> rassemble <span>les</span> cardiopathies à <strong>risque intermédiaire</strong> d'EI :</p>\n      <ul>\n        <li><span><span class=\"nc-brown_bg\">Valvulopathies dégénératives</span></span> ;</li>\n        <li><span class=\"nc-orange_bg\">Valvulopathies congénitales n'entrant pas dans le groupe A</span> — ex. <span>bicuspidie aortique</span> ;</li>\n        <li><span><span class=\"nc-orange_bg\">Cardiopathie post-rhumatismale</span></span> ;</li>\n        <li><span><span class=\"nc-orange_bg\">Cardiomyopathie hypertrophique</span></span> ;</li>\n        <li><span><span class=\"nc-pink_bg\">Stimulateur</span></span><span class=\"nc-pink_bg\"> et </span><span><span class=\"nc-pink_bg\">défibrillateur</span></span><span class=\"nc-pink_bg\"> cardiaque implantables</span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Discriminant.</strong> Le groupe B est à risque intermédiaire : il <span>ne relève pas de l'antibioprophylaxie</span>, réservée au seul <span>groupe A</span> (haut risque). Tous deux relèvent en revanche de l'<span>éducation à la santé</span>.</div></div>"},{"i":"6a4ecc94c0bc","n":152,"o":"152-7","u":"Diagnostic positif","t":"Connaître les signes cliniques évocateurs EI","q":"Quels sont les points essentiels concernant les signes cliniques évocateurs EI ?","a":"<div class=\"notion-course\"><p>Le tableau évocateur d'EI repose sur l'association d'une <span><span class=\"nc-yellow_bg\">fièvre</span></span> avec au moins l'un des éléments suivants : <strong>cardiopathie à risque</strong>, <strong><span class=\"nc-yellow_bg\">souffle cardiaque</span></strong>, <strong><span class=\"nc-yellow_bg\">accident </span><span><span class=\"nc-yellow_bg\">ischémique</span></span></strong>, <strong><span><span class=\"nc-yellow_bg\">purpura</span></span></strong> ou <strong><span class=\"nc-yellow_bg\">lombalgie</span></strong>.</p>\n      <table>\n        <thead><tr><th>Domaine</th><th>Signes</th></tr></thead>\n        <tbody>\n          <tr><td><span>Syndrome <span>infectieux</span></span></td><td><span>Fièvre</span> ; <span>AEG</span> ; <span>splénomégalie</span> (<span>20-30 %</span>)</td></tr>\n          <tr><td>Signes cardiaques</td><td><strong>Souffle :</strong> apparition ou modification d'un <span>souffle</span> — grande valeur diagnostique ; <span>son absence n'élimine pas le diagnostic</span><br><strong><span>Insuffisance cardiaque</span> :</strong> <span>fébrile</span>, surtout gauche<br><strong>Conduction :</strong> <span>syncope</span> ou <span>lipothymie</span> par <span><span class=\"nc-red nc-bold\">BAV</span></span> (<span><span class=\"nc-pink nc-bold\">abcès</span></span><span class=\"nc-pink nc-bold\"> septal</span>)<br><strong><span class=\"nc-orange_bg\">Péricardite</span> :</strong> plus rare</td></tr>\n          <tr><td>Phénomènes <strong>vasculaires</strong><br>(emboles septiques)</td><td><span>Lésions de Janeway</span> — <span>érythème</span> palmoplantaire indolore<br><span>Hémorragies sous-unguéales</span> « en flammèche »<br>Emboles artériels ; anévrismes mycotiques</td></tr>\n          <tr><td>Phénomènes <strong>immunologiques</strong><br>(complexes immuns)</td><td><span class=\"nc-blue_bg\">Faux </span><span><span class=\"nc-blue_bg\">panaris</span></span><span class=\"nc-blue_bg\"> d'</span><span><span class=\"nc-blue_bg\">Osler</span></span> — <span class=\"nc-blue nc-bold\">nodosités douloureuses</span>, fugaces, pulpe des doigts/orteils<br><span>Taches de Roth</span> — exsudats hémorragiques rétiniens (<span>fond d'œil</span>)<br><span>Glomérulonéphrite</span> ; <span>facteur rhumatoïde</span><br><span>Purpura vasculaire</span></td></tr>\n        </tbody>\n      </table>\n      \n      <p>Cette planche illustre <span>les</span> quatre signes périphériques : l'<span>hémorragie sous-unguéale</span> et la <span>lésion de Janeway</span> sont des phénomènes <strong>vasculaires</strong> (emboles septiques) ; la <span>nodosité d'Osler</span> et la <span>tache de Roth</span> sont des phénomènes <strong>immunologiques</strong> (dépôts de complexes immuns).</p>\n      <div class=\"callout callout-warn\"><strong>Discriminant EDN — Osler <span>vs</span> Janeway.</strong> <span>Osler</span> = nodosité <span>douloureuse</span>, phénomène <strong>immunologique</strong>. <span>Janeway</span> = <span>macule</span> <span>indolore</span>, phénomène <strong>vasculaire</strong> (embole septique).</div>\n      <div class=\"callout callout-warn\"><strong>Tableaux trompeurs.</strong> <span><span class=\"nc-yellow_bg\">Fièvre</span></span> nue aiguë ou prolongée, <span>arthralgies</span> ou <span>lombalgies fébriles</span>, forme révélée par une complication inaugurale, ou alternance <span><span class=\"nc-yellow_bg\">fièvre</span></span> / apyrexie — la <span>récidive de la <span class=\"nc-yellow_bg\">fièvre</span> à l'arrêt d'une antibiothérapie</span> est très évocatrice.</div>\n      <p><strong>Forme aiguë <span>vs</span> subaiguë</strong> — la forme <span>aiguë</span> (<span>S. aureus</span>) associe <span>sepsis</span> au premier plan, <span>insuffisance cardiaque</span> et risque d'<span><span class=\"nc-red nc-bold\">AVC</span></span>. L'<span><span class=\"nc-green_bg\">endocardite</span></span><span class=\"nc-green_bg\"> </span><span><span class=\"nc-green_bg\">subaiguë d'Osler</span></span> (<span><span class=\"nc-green_bg\">streptocoque</span></span>, <span><span class=\"nc-green_bg\">entérocoque</span></span>) évolue sur plusieurs semaines : <span><span class=\"nc-yellow_bg\">fièvre</span> &gt; 8 jours</span>, <span>AEG</span>, phénomènes auto-immuns circulants.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 147 — <span>Fièvre</span> aiguë</em></p></div>"},{"i":"ec15d8443f1e","n":152,"o":"152-8","u":"Diagnostic positif","t":"Connaître la démarche initiale du diagnostic microbiologique","q":"Quels sont les points essentiels concernant la démarche initiale du diagnostic microbiologique ?","a":"<div class=\"notion-course\"><ul><li>Prélever plusieurs paires d’<span class=\"nc-yellow_bg nc-bold\">hémocultures</span> périphériques avant antibiotiques, sans attendre un pic fébrile. Le volume est déterminant : chez l’adulte, environ 10 mL/flacon, soit habituellement trois paires ; volumes pédiatriques adaptés.</li><li>En cas de <span class=\"nc-red nc-bold\">sepsis</span> ou indication urgente, regrouper les prélèvements rapidement et ne pas attendre 24 heures pour traiter. Chez le patient stable, respecter le protocole microbiologique d’endocardite.</li><li>Informer le laboratoire, préciser antibiotiques antérieurs et suspicion de germe difficile. Une incubation prolongée de 14 jours n’est pas obligatoire pour toutes les EI avec les systèmes actuels ; discuter les recherches spécifiques.</li></ul></div>"},{"i":"9890b17ca00d","n":152,"o":"152-9","u":"Diagnostic positif","t":"Connaître la démarche du diagnostic microbiologique quand les hémocultures initiales sont négatives","q":"Quels sont les points essentiels concernant la démarche du diagnostic microbiologique quand les hémocultures initiales sont négatives ?","a":"<div class=\"notion-course\"><ul><li>Première cause d’hémocultures négatives : antibiotiques préalables. Vérifier volumes et modalités, contacter microbiologiste/infectiologue ; ne pas <span class=\"nc-pink nc-bold\">interrompre</span> automatiquement un traitement pour une fenêtre de 72 heures.</li><li>Selon expositions et contexte : sérologies Coxiella et <span class=\"nc-purple nc-bold\">Bartonella</span>, examens ciblés <span class=\"nc-purple nc-bold\">Brucella</span>, <span class=\"nc-blue_bg\">PCR</span> pour agents difficiles dont <span class=\"nc-purple nc-bold\">Tropheryma whipplei</span>, mycologie. Les techniques sont choisies avec le laboratoire.</li><li>Si chirurgie : analyse anatomopathologique, cultures et biologie moléculaire de la valve/matériel. En parallèle, considérer une endocardite non infectieuse.</li><li>Une bactérie rare ne doit pas être exclue par une affirmation absolue « ne donne jamais d’endocardite ». Rechercher surtout les causes probables et accessibles aux tests validés.</li></ul></div>"},{"i":"c6fbdd6228c7","n":152,"o":"152-10","u":"Diagnostic positif","t":"Connaître la démarche initiale du diagnostic échocardiographie en cas de suspicion d'EI","q":"Quels sont les points essentiels concernant la démarche initiale du diagnostic échocardiographie en cas de suspicion d'EI ?","a":"<div class=\"notion-course\"><p>L'<span><span class=\"nc-blue nc-bold\">échographie cardiaque</span></span> est, avec <span>les</span> <span>hémocultures</span>, l'un des deux <strong>piliers diagnostiques</strong> de l'EI.</p>\n      <table>\n        <thead><tr><th>Examen</th><th>Indication</th><th>Sensibilité</th></tr></thead>\n        <tbody>\n          <tr><td><span><span class=\"nc-blue_bg\">ETT</span></span> — transthoracique</td><td><strong>1ʳᵉ intention, systématique</strong> dans tous <span>les</span> cas</td><td><span>~70 %</span></td></tr>\n          <tr><td><span><span class=\"nc-blue_bg\">ETO</span></span> — transœsophagienne</td><td>Si <span><span class=\"nc-red nc-bold\">ETT</span></span><span class=\"nc-red nc-bold\"> positive</span> ; ou <span><span class=\"nc-red nc-bold\">ETT</span></span><span class=\"nc-red nc-bold\"> négative avec </span><span><span class=\"nc-red nc-bold\">forte suspicion</span></span> ; ou présence de <strong><span class=\"nc-red nc-bold\">matériel intracardiaque</span></strong></td><td><span>≥ 90 %</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> Une <span><span class=\"nc-green_bg\">échographie normale n'élimine pas</span></span><span class=\"nc-green_bg\"> le diagnostic</span>. En cas de <span class=\"nc-red nc-bold\">forte suspicion</span> clinique, elle doit être <strong>répétée à <span><span class=\"nc-pink nc-bold\">J7-J10</span></span></strong> (<span><span class=\"nc-blue_bg\">ETT</span></span> + <span><span class=\"nc-blue_bg\">ETO</span></span>).</div>\n      <p>Le <span>diagnostic positif</span> s'appuie sur <span>les</span> <strong><span>critères diagnostiques</span> de Duke modifiés (<span>2023</span>)</strong>, qui combinent critères <span>majeurs</span> et <span>mineurs</span> :</p>\n      <table>\n        <thead><tr><th><span>Critères majeurs</span> (2)</th><th><span>Critères mineurs</span> (5)</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>\n              <strong><span>Hémocultures</span> positives pour l'EI :</strong>\n              <ul>\n                <li><span>≥ 2 hémocultures</span> à micro-organisme <strong>typique d'EI</strong> (<span><span class=\"nc-purple nc-bold\">S. aureus</span></span>, <span><span class=\"nc-purple nc-bold\">streptocoques oraux</span></span>, <span><span class=\"nc-purple_bg\">S. gallolyticus</span></span>, <span><span class=\"nc-purple nc-bold\">entérocoques</span></span>, <span><span class=\"nc-purple nc-bold\">HACEK</span></span>) ;</li>\n                <li>ou <span>≥ 1</span> <span>hémoculture</span> ou <span>sérologie</span> positive à <span><span class=\"nc-purple nc-bold\">Coxiella burnetii</span></span> (<span>IgG phase I &gt; 1/800</span>).</li>\n              </ul>\n              <strong><span>Imagerie</span> positive pour <span>les</span> lésions d'EI :</strong>\n              <ul>\n                <li><span><span class=\"nc-blue nc-bold\">échographie cardiaque</span></span> (<span class=\"nc-red_bg\">végétations</span>, <span><span class=\"nc-red_bg\">abcès</span></span>, <span class=\"nc-red_bg\">faux anévrisme</span>, <span class=\"nc-red_bg\">fistule</span>, <span class=\"nc-red_bg\">destruction valvulaire</span>, <span class=\"nc-red_bg\">désinsertion de prothèse</span>) ;</li>\n                <li>ou <span><span class=\"nc-blue nc-bold\">TEP-scan</span></span> / <span><span class=\"nc-blue_bg\">scintigraphie aux leucocytes marqués</span></span> ;</li>\n                <li>ou <span>scanner cardiaque</span> (<span><span class=\"nc-red_bg\">abcès</span></span>, <span class=\"nc-red_bg\">faux anévrisme</span>, <span class=\"nc-red_bg\">fistule</span>).</li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li><span>Terrain</span> : patient à haut risque ou risque intermédiaire d'EI, ou toxicomanie IV ;</li>\n                <li><span>Fièvre</span> ≥ <span>38 °C</span> ;</li>\n                <li><span>Phénomènes vasculaires</span> : embolies artérielles ou pulmonaires, <span class=\"nc-blue_bg\">anévrismes </span><span><span class=\"nc-blue_bg\">infectieux</span></span><span class=\"nc-blue_bg\"> (mycotiques)</span>, <span class=\"nc-blue_bg\">hémorragies</span>, <span class=\"nc-blue_bg\">placards de Janeway</span> ;</li>\n                <li><span>Phénomènes immunologiques</span> : <span class=\"nc-orange_bg\">glomérulonéphrite</span>, <span class=\"nc-orange_bg\">nodosités d'Osler</span>, <span class=\"nc-orange_bg\">taches de Roth</span>, <span class=\"nc-orange_bg\">facteurs rhumatoïdes</span> ;</li>\n                <li><span>Argument microbiologique</span> n'entrant pas dans la définition d'un <span>critère majeur</span> (<span>hémocultures</span>, <span>sérologies</span>).</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Seuils diagnostiques (EI certaine).</strong> <span>2 critères majeurs</span>, ou <span>1 majeur + 3 mineurs</span>, ou <span><span class=\"nc-red_bg nc-bold\">5 critères mineurs</span></span> (à défaut d'un critère histologique). <strong>EI possible</strong> : 1 majeur + 1-<span <span=\"\">&gt;2</span> mineurs, ou 3 mineurs.</div></div>"},{"i":"10ad0e67d710","n":152,"o":"152-11","u":"Diagnostic positif","t":"Connaître les arguments échocardiographiques du diagnostic d'EI","q":"Quels sont les points essentiels concernant les arguments échocardiographiques du diagnostic d'EI ?","a":"<div class=\"notion-course\"><p>L'<span><span class=\"nc-blue nc-bold\">échographie cardiaque</span></span> (<span>ETT</span> puis <span>ETO</span>) recherche <span>les</span> <span>lésions caractéristiques d'EI</span> :</p>\n      <ul>\n        <li><span>Végétations</span> — <span>lésion</span> élémentaire proliférante de l'EI ;</li>\n        <li><span><span class=\"nc-yellow_bg\">Destructions valvulaires</span></span> — perforation, mutilation, <span>rupture</span> de cordage ;</li>\n        <li><span><span class=\"nc-red_bg\">Abcès</span></span> et <span>faux anévrisme</span> ;</li>\n        <li><span>Fistules intracardiaques</span> ;</li>\n        <li><span>Désinsertion de prothèse</span> et <span><span class=\"nc-red nc-bold\">fuite paraprothétique</span></span>.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong><span>Critère de</span> Duke.</strong> Une imagerie positive pour ces lésions est un <span>critère majeur</span> des <span>critères de</span> Duke modifiés (<span>2023</span>), au même titre qu'un <span>TEP-scanner</span> ou une <span><span class=\"nc-blue_bg\">scintigraphie aux leucocytes marqués</span></span> positifs, ou un <span>scanner cardiaque</span> montrant <span><span class=\"nc-red_bg\">abcès</span></span>, <span class=\"nc-red_bg\">faux anévrisme</span> ou <span class=\"nc-red_bg\">fistule</span>.</div></div>"},{"i":"fc33c788a085","n":152,"o":"152-12","u":"Examens complémentaires","t":"Savoir hiérarchiser les examens complémentaires en fonction de l'état clinique du patient (hémocultures, échocardiographie, autres examens complémentaires)","q":"Quels sont les points essentiels concernant hiérarchiser les examens complémentaires en fonction de l'état clinique du patient (hémocultures, échocardiographie, autres examens complémentaires) ?","a":"<div class=\"notion-course\"><p>Le bilan se hiérarchise autour des <strong>deux piliers</strong> — <span><span class=\"nc-yellow_bg nc-bold\">hémocultures</span></span> et <span><span class=\"nc-blue nc-bold\">échographie cardiaque</span></span> — complétés selon l'état clinique du patient.</p>\n      <table>\n        <thead><tr><th>Niveau</th><th>Examens</th></tr></thead>\n        <tbody>\n          <tr><td>Piliers diagnostiques</td><td><strong><span>Hémocultures</span> :</strong> <span>mise en évidence du germe</span><br><strong><span>Échographie cardiaque</span> :</strong> <span>ETT</span> puis <span>ETO</span> — confirme l'atteinte de l'endocarde</td></tr>\n          <tr><td>Si <span>échographie</span> non contributive</td><td><strong><span><span class=\"nc-blue_bg\">TDM</span></span><span class=\"nc-blue_bg\"> cardiaque</span> :</strong> <span><span class=\"nc-orange nc-bold\">abcès</span></span> non vus à l'écho, surtout si prothèse<br><strong><span>TEP-scanner 18-FDG</span> / <span><span class=\"nc-blue_bg\">scintigraphie aux leucocytes marqués</span></span> :</strong> hyperfixation, EI sur prothèse ; dépiste <span>les</span> localisations septiques</td></tr>\n          <tr><td>Biologie</td><td><strong><span><span class=\"nc-blue_bg\">NFS</span></span> :</strong> <span>hyperleucocytose à PNN</span> ; <span>anémie</span> ; <span>thrombopénie</span><br><strong>Inflammation :</strong> <span><span class=\"nc-blue_bg\">CRP</span></span> élevée<br><strong>Retentissement :</strong> <span>ionogramme</span> ; <span><span class=\"nc-blue_bg\">créatininémie</span></span> ; <span>BU</span><br><strong>Immunologie :</strong> <span><span class=\"nc-pink_bg\">facteur rhumatoïde</span></span> ; <span>complément</span> ; <span><span class=\"nc-pink_bg\">cryoglobulinémie</span></span></td></tr>\n          <tr><td>Retentissement cardiaque</td><td><strong><span>ECG</span> :</strong> trouble de conduction (<span><span class=\"nc-red nc-bold\">BAV</span></span>) ; <span><span class=\"nc-red nc-bold\">ischémie myocardique</span></span> (embolie coronarienne)</td></tr>\n          <tr><td>Localisations secondaires</td><td><strong><span><span class=\"nc-blue_bg\">RXT</span></span> :</strong> <span>OAP</span> (EI cœur gauche) ou pneumopathie (EI cœur droit)<br><strong><span><span class=\"nc-yellow_bg\">TDM</span> corps entier injectée</span> :</strong> localisations septiques ; anévrismes mycotiques<br><strong><span>IRM cérébrale</span> :</strong> plus sensible que le <span>scanner</span>, sur point d'appel<br><strong><span>Coronarographie</span>, <span><span class=\"nc-blue_bg\">troponine</span></span> :</strong> si embolie coronarienne suspectée</td></tr>\n        </tbody>\n      </table></div>"},{"i":"3db72ad42e42","n":152,"o":"152-13","u":"Examens complémentaires","t":"Connaître les principales localisations emboliques en cas d'EI","q":"Quels sont les points essentiels concernant les principales localisations emboliques en cas d'EI ?","a":"<div class=\"notion-course\"><p><span>Les</span> emboles proviennent des <span>végétations</span> ; leur localisation dépend du côté du cœur atteint.</p>\n      <table>\n        <thead><tr><th>Origine</th><th>Localisations emboliques</th></tr></thead>\n        <tbody>\n          <tr><td>EI du <strong>cœur gauche</strong><br>(emboles systémiques)</td><td><strong>Cérébral :</strong> <span><span class=\"nc-red nc-bold\">AVC</span></span>, <span>AIT</span>, <span>convulsions</span>, <span><span class=\"nc-red nc-bold\">syndrome méningé</span></span> — <span>~25 %</span> des cas, <span>2ᵉ cause de décès</span><br><strong>Viscéral :</strong> <span><span class=\"nc-red nc-bold\">rate</span></span>, <span><span class=\"nc-red nc-bold\">reins</span></span>, <span><span class=\"nc-red nc-bold\">foie</span></span> — <span><span class=\"nc-red nc-bold\">abcès</span></span> ou <span>infarctus</span><br><strong>Ostéo-articulaire :</strong> <span><span class=\"nc-red nc-bold\">arthrite</span></span> ; <span>spondylodiscite</span><br><strong>Membres :</strong> <span>ischémie aiguë</span> ou subaiguë<br><strong>Coronaire :</strong> <span><span class=\"nc-red nc-bold\">ischémie myocardique</span></span></td></tr>\n          <tr><td>EI du <strong>cœur droit</strong></td><td><strong><span class=\"nc-red nc-bold\">Embolies pulmonaires septiques</span> :</strong> fréquemment multiples — <span><span class=\"nc-red nc-bold\">infarctus pulmonaires</span></span>, <span>abcès</span><br><strong>Pneumopathies :</strong> <span>récidivantes</span> et <span>abcédées</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Anévrismes mycotiques.</strong> Anévrismes <span>infectieux</span> de toute localisation — ils exposent à une <span>hémorragie cataclysmique</span> par <span>rupture</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 340 — <span>AVC</span> · 156 — Infection ostéo-articulaire</em></p></div>"},{"i":"0763d5ca485f","n":152,"o":"152-14","u":"Identifier une urgence","t":"Savoir quand une antibiothérapie probabiliste est indiquée en cas de suspicion d'EI","q":"Quels sont les points essentiels concernant quand une antibiothérapie probabiliste est indiquée en cas de suspicion d'EI ?","a":"<div class=\"notion-course\"><p>L'<span>antibiothérapie probabiliste</span> est instaurée <strong>après <span>les</span> <span><span class=\"nc-yellow_bg nc-bold\">hémocultures</span></span></strong> et <strong>avant leur résultat</strong>. Elle n'est justifiée que dans trois situations :</p>\n      <ul>\n        <li><span><span class=\"nc-red nc-bold\">Forte suspicion</span></span> d'EI — surtout si <span>images évocatrices</span> à l'<span><span class=\"nc-blue nc-bold\">échographie cardiaque</span></span> ;</li>\n        <li><span><span class=\"nc-red nc-bold\">Sepsis sévère</span></span> ;</li>\n        <li><span><span class=\"nc-red nc-bold\">Indication chirurgicale urgente</span></span>.</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Règle d'or.</strong> Hors de ces situations, on <strong>attend la <span>documentation microbiologique</span></strong>. Dans tous <span>les</span> cas, les <span><span class=\"nc-yellow_bg nc-bold\">hémocultures</span></span> sont prélevées <em>avant</em> toute <span>antibiothérapie</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 158 — <span>Sepsis</span> et <span>choc septique</span></em></p></div>"},{"i":"f5a9ab37d4d5","n":152,"o":"152-15","u":"Prise en charge","t":"Connaître les principes du traitement antibiotique de l'EI","q":"Quels sont les points essentiels concernant les principes du traitement antibiotique de l'EI ?","a":"<div class=\"notion-course\"><ul><li>Prise en charge initiale hospitalière, équipe multidisciplinaire d’endocardite. Antibiotiques à doses et diffusion adaptées, guidés par espèce, sensibilité, valve native/prothèse et complications.</li><li>Durée souvent quatre à six semaines, mais variable selon agent et situation. La chirurgie ne remet pas systématiquement le compteur à zéro ; microbiologie opératoire et évolution guident la décision.</li><li>Les associations et aminosides ne sont pas <span class=\"nc-yellow_bg nc-bold\">systématiques</span>. Relais oral possible chez certains patients stables et sélectionnés, après évaluation spécialisée ; éviter la règle « tout IV pendant toute la durée ».</li><li>Surveillance clinique, <span class=\"nc-yellow_bg nc-bold\">hémocultures</span>, rein/foie, concentrations si nécessaire et échographie. Trois motifs majeurs de chirurgie : insuffisance cardiaque, infection non contrôlée, prévention embolique ; urgence et risque neurologique discutés en équipe.</li></ul></div>"},{"i":"28c350190dfe","n":152,"o":"152-16","u":"Prise en charge","t":"Connaître les modalités de prise en charge de la porte d'entrée d'une EI","q":"Quels sont les points essentiels concernant les modalités de prise en charge de la porte d'entrée d'une EI ?","a":"<div class=\"notion-course\"><p>Le <strong>traitement de la <span><span class=\"nc-orange_bg\">porte d'entrée</span></span></strong> est indispensable : sans lui, le risque de <span>récidive</span> persiste. Sa recherche et sa prise en charge dépendent du germe identifié.</p>\n      <table>\n        <thead><tr><th>Origine</th><th>Germes</th><th>Prise en charge</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"nc-yellow_bg\">Cutanée</span></td><td><span>S. aureus</span>, staph. à coagulase négative</td><td>Examen du revêtement cutané ; <span>ablation et culture du cathéter</span></td></tr>\n          <tr><td><span class=\"nc-blue_bg\">Bucco-dentaire</span></td><td><span><span class=\"nc-purple_bg\">Streptocoques oraux</span></span>, <span><span class=\"nc-purple_bg\">HACEK</span></span></td><td><span><span class=\"nc-blue_bg\">Panoramique dentaire</span></span> ; consultation et soins stomatologiques</td></tr>\n          <tr><td>Digestive</td><td><span><span class=\"nc-purple_bg\">S. gallolyticus</span></span>, <span><span class=\"nc-purple_bg\">entérocoques</span></span></td><td><span><span class=\"nc-blue_bg\">Coloscopie totale</span></span> ; <span><span class=\"nc-blue_bg\">imagerie abdominale</span></span> et des voies biliaires ; recherche d'une <span>tumeur colique</span></td></tr>\n          <tr><td>Urinaire</td><td><span><span class=\"nc-purple_bg\">Entérocoques</span></span></td><td><span><span class=\"nc-blue_bg\">ECBU</span></span> ; <span>échographie</span> ou <span>scanner</span> des voies urinaires</td></tr>\n        </tbody>\n      </table></div>"},{"i":"fa73a0f1005c","n":152,"o":"152-17","u":"Prise en charge","t":"Connaître les principes d'éducation à la santé après un épisode d'EI","q":"Quels sont les points essentiels concernant les principes d'éducation à la santé après un épisode d'EI ?","a":"<div class=\"notion-course\"><p>L'éducation à la santé concerne <strong>tous <span>les</span> patients porteurs d'une <span class=\"nc-yellow_bg\">cardiopathie à risque</span></strong><span class=\"nc-yellow_bg\"> d'EI</span> (<span>groupe A</span> ou <span>groupe B</span>). Mesures à connaître :</p>\n      <ul>\n        <li>Maintenir une bonne <strong><span>hygiène <span class=\"nc-blue_bg\">bucco-dentaire</span></span></strong> ;</li>\n        <li><span>Consultation chez le dentiste</span> — <span>2×/an</span> si cardiopathie à haut risque, <span>1×/an</span> pour <span>les</span> autres ;</li>\n        <li><span>Désinfecter les plaies</span> ;</li>\n        <li>Éradiquer <span>les</span> <span>colonisations bactériennes chroniques</span> — cutanées et urinaires ;</li>\n        <li>Traiter <span>les</span> <span>infections bactériennes locales</span> par antibiotiques ;</li>\n        <li><span>Asepsie stricte</span> lors des procédures à risque de <span>bactériémie</span> ;</li>\n        <li>Éviter <span>les</span> effractions cutanées — <span>tatouages</span>, <span>piercings</span> ;</li>\n        <li>Limiter et renouveler <span>les</span> <span>voies veineuses</span> ;</li>\n        <li>Éviter l'<span>automédication par antibiotiques</span> et consulter rapidement en cas de <span>fièvre</span>.</li>\n      </ul></div>"},{"i":"7206ddba7587","n":152,"o":"152-18","u":"Prise en charge","t":"Connaître les principes de l'antibioprophylaxie de l'EI (groupe de cardiopathie à risque, gestes à risque)","q":"Quels sont les points essentiels concernant les principes de l'antibioprophylaxie de l'EI (groupe de cardiopathie à risque, gestes à risque) ?","a":"<div class=\"notion-course\"><ul><li>La prophylaxie dentaire concerne les patients à haut risque et les gestes exposants : manipulation gingivale/périapicale ou effraction muqueuse. Hygiène quotidienne et suivi dentaire restent essentiels.</li><li>Repère adulte sans allergie : <span class=\"nc-pink_bg\">amoxicilline</span> 2 g, 30–60 minutes avant le geste. Enfant : 50 mg/kg, sans dépasser 2 g. Alternatives selon type d’allergie, voie et recommandation française actualisée ; ne pas prescrire une céphalosporine automatiquement après anaphylaxie à pénicilline.</li><li>Ne pas confondre prophylaxie de l’endocardite et antibioprophylaxie propre à une intervention chirurgicale. L’assertion « aucune autre chirurgie ne nécessite de prophylaxie » est fausse.</li><li>Pour les autres procédures, appliquer le cadre SPILF/AEPEI et les recommandations spécifiques ; ne pas extrapoler la liste des gestes dentaires à toute intervention.</li></ul></div>"},{"i":"c1911f01a13e","n":152,"o":"152-19","u":"Suivi et/ou pronostic","t":"Connaître les principales complications des EI : complications cardiaques, complications emboliques, complications infectieuses","q":"Quels sont les points essentiels concernant les principales complications des EI : complications cardiaques, complications emboliques, complications infectieuses ?","a":"<div class=\"notion-course\"><p><span>Les</span> complications de l'EI se répartissent en trois groupes — c'est le plan même de l'intitulé officiel.</p>\n      <table>\n        <thead><tr><th>Type</th><th>Complications</th></tr></thead>\n        <tbody>\n          <tr><td>Cardiaques</td><td><span class=\"nc-red_bg\">Destruction valvulaire</span> → <span><span class=\"nc-red nc-bold\">régurgitation</span></span> <span class=\"nc-red nc-bold\">valvulaire</span> ou paraprothétique ; <span><span class=\"nc-red nc-bold\">insuffisance cardiaque aiguë</span></span> (<span>OAP</span>, <span>choc cardiogénique</span>) ; <span><span class=\"nc-red_bg\">abcès</span></span> → <span><span class=\"nc-red nc-bold\">BAV</span></span> (<span><span class=\"nc-pink nc-bold\">abcès</span></span><span class=\"nc-pink nc-bold\"> septal</span> des <span class=\"nc-pink nc-bold\">EI aortiques</span>), et par <span>rupture</span> → <span>faux anévrisme</span> ou <span><span class=\"nc-red nc-bold\">fistule intracardiaque</span></span> ; <span><span class=\"nc-red_bg\">désinsertion de prothèse</span></span></td></tr>\n          <tr><td>Emboliques</td><td>Emboles systémiques (cœur gauche) → <span><span class=\"nc-red nc-bold\">AVC</span></span>, <span><span class=\"nc-red nc-bold\">abcès</span></span> spléniques / rénaux / hépatiques ; <span><span class=\"nc-red nc-bold\">embolies pulmonaires septiques</span></span> (cœur droit) ; <span><span class=\"nc-blue_bg\">anévrismes infectieux (mycotiques)</span></span> à risque <span>hémorragique</span></td></tr>\n          <tr><td>Infectieuses</td><td><span>Choc septique</span> ; <span class=\"nc-red nc-bold\">foyers </span><span><span class=\"nc-red nc-bold\">infectieux</span></span><span class=\"nc-red nc-bold\"> à distance</span> — <span><span class=\"nc-red nc-bold\">spondylodiscite</span></span>, <span><span class=\"nc-red nc-bold\">arthrite</span></span>, <span>méningite</span>, <span><span class=\"nc-red nc-bold\">abcès</span></span> ; infection localement non contrôlée</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong><span>Les</span> deux causes de décès.</strong> L'<span><span class=\"nc-red nc-bold\">insuffisance cardiaque</span></span> est la <span>1ʳᵉ</span> cause de <span>mortalité</span> de l'EI, les <span><span class=\"nc-red nc-bold\">emboles cérébraux</span></span> la <span>2ᵉ</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 234 — <span>Insuffisance cardiaque</span> · 340 — <span>AVC</span></em></p></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/2ad37f85d94181b28f14ddf1c61f2579?pvs=204","reviewedAt":"2026-10-16","batch":"digestive-infectious-50","verification":"reviewed","note":"Relecture et contrôles du lot réalisés. LiSA : copies locales ; ordinateur et format iPad simulé."}};
